app.get('/password/change',needAuth,(req,res)=>res.send(page('Aggiorna password',`${takeFlash(req)}<section class="card"><p>Per continuare devi sostituire la password temporanea.</p><form method="post" action="/password/change">${formToken(req)}${input('Nuova password (almeno 12 caratteri)','password','password','',true)}${input('Conferma password','confirm','password','',true)}<button class="button primary">Aggiorna password</button></form></section>`,req.session.user)));
app.post('/password/change',needAuth,async(req,res,next)=>{try{const password=String(req.body.password||'');if(password.length<12||password!==req.body.confirm)throw new Error('Le password devono coincidere e contenere almeno 12 caratteri.');const hash=await bcrypt.hash(password,12);await pool.query('UPDATE users SET password_hash=$1,must_change_password=false WHERE id=$2',[hash,req.session.user.id]);await pool.query("DELETE FROM user_sessions WHERE sess->'user'->>'id'=$1 AND sid<>$2",[String(req.session.user.id),req.sessionID]);req.session.user.mustChangePassword=false;flash(req,'Password aggiornata.');res.redirect('/');}catch(e){flash(req,e.message);res.redirect('/password/change');}});
app.get('/search',needAuth,async(req,res,next)=>{try{const term=String(req.query.q||'').trim().slice(0,80);if(!term)return res.redirect('/');const pattern=`%${term}%`;const [customers,vehicles,orders]=await Promise.all([pool.query(`SELECT id,name,phone FROM customers WHERE name ILIKE $1 OR phone ILIKE $1 ORDER BY name LIMIT 12`,[pattern]),pool.query(`SELECT v.id,v.plate,v.make,v.model,c.name AS customer FROM vehicles v JOIN customers c ON c.id=v.customer_id WHERE v.plate ILIKE $1 OR v.vin ILIKE $1 OR v.make ILIKE $1 OR v.model ILIKE $1 ORDER BY v.plate LIMIT 12`,[pattern]),pool.query(`SELECT w.id,w.status,v.plate,c.name AS customer FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id WHERE w.id::text ILIKE $1 OR concat('GO-',w.id) ILIKE $1 ORDER BY w.created_at DESC LIMIT 12`,[pattern])]);const list=(rows,render,cols)=>rows.map(render).join('')||`<tr><td colspan="${cols}" class="empty">Nessun risultato</td></tr>`;const body=`<p class="muted">Risultati per: <strong>${esc(term)}</strong></p><section class="card"><h2>Clienti</h2><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Telefono</th></tr></thead><tbody>${list(customers.rows,c=>`<tr><td><a href="/customers/${c.id}">${esc(c.name)}</a></td><td>${esc(c.phone||'—')}</td></tr>`,2)}</tbody></table></div></section><section class="card"><h2>Veicoli</h2><div class="table-wrap"><table><thead><tr><th>Targa</th><th>Veicolo</th><th>Cliente</th></tr></thead><tbody>${list(vehicles.rows,v=>`<tr><td><a href="/vehicles/${v.id}">${esc(v.plate)}</a></td><td>${esc(v.make)} ${esc(v.model)}</td><td>${esc(v.customer)}</td></tr>`,3)}</tbody></table></div></section><section class="card"><h2>Ordini di lavoro</h2><div class="table-wrap"><table><thead><tr><th>Ordine</th><th>Targa</th><th>Cliente</th><th>Stato</th></tr></thead><tbody>${list(orders.rows,w=>`<tr><td><a href="/work-orders/${w.id}">GO-${w.id}</a></td><td>${esc(w.plate)}</td><td>${esc(w.customer)}</td><td>${esc(statuses[w.status]||w.status)}</td></tr>`,4)}</tbody></table></div></section>`;res.send(page('Ricerca',body,req.session.user));}catch(e){next(e);}});
app.get('/register',(req,res)=>res.send(page('Richiedi accesso',`${takeFlash(req)}<section class="card"><p>Invia la richiesta di attivazione della tua officina. L’account sarà creato soltanto dopo l’approvazione.</p><form method="post" action="/register">${formToken(req)}<div class="form-grid">${input('Nome officina','workshop_name','text','',true)}${input('Nome titolare','owner_name','text','',true)}${input('Email titolare','email','email','',true)}${input('Telefono','phone')}${input('Password iniziale (almeno 12 caratteri)','password','password','',true)}</div><button class="button primary">Invia richiesta</button></form></section>`)));
app.post('/register',async(req,res,next)=>{try{const workshopName=String(req.body.workshop_name||'').trim(),ownerName=String(req.body.owner_name||'').trim(),email=String(req.body.email||'').trim().toLowerCase(),password=String(req.body.password||'');if(!workshopName||!ownerName||!email.includes('@')||password.length<12)throw new Error('Compila i campi richiesti e usa una password di almeno 12 caratteri.');const hash=await bcrypt.hash(password,12);await pool.query('INSERT INTO registration_requests(workshop_name,owner_name,email,phone,password_hash) VALUES($1,$2,$3,$4,$5)',[workshopName,ownerName,email,String(req.body.phone||'').slice(0,60),hash]);flash(req,'Richiesta inviata. Riceverai conferma dopo la revisione.');res.redirect('/register');}catch(e){flash(req,e.code==='23505'?'Esiste già una richiesta con questa email.':e.message);res.redirect('/register');}});
app.get('/login', (req,res) => req.session.user ? res.redirect('/') : res.send(page('Accedi', `${takeFlash(req)}<section class="login-card card"><img src="/assets/brand/go-logo.png" alt="GO Gestione Officina"><h2>Accedi al gestionale</h2><form method="post" action="/login">${formToken(req)}${input('Email','email','email','',true)}${input('Password','password','password','',true)}<button class="button primary">Accedi</button></form><p class="muted"><a href="/register">Richiedi la registrazione di un’officina</a></p><p class="muted"><a href="/superuser/login">Accesso superuser</a></p></section>`)));
app.post('/login', async (req,res,next) => { try { const result=await pool.query('SELECT id,name,email,password_hash,role,workshop_id,must_change_password FROM users WHERE lower(email)=lower($1) AND active=true',[req.body.email||'']); const u=result.rows[0]; if (!u || !await bcrypt.compare(req.body.password||'',u.password_hash)) { flash(req,'Email o password non corretti.'); return res.redirect('/login'); } await pool.query('UPDATE users SET last_login_at=now() WHERE id=$1',[u.id]); req.session.regenerate(err=>{ if(err)return next(err); const token=crypto.randomBytes(24).toString('hex'); req.session.csrf=token; req.session.user={id:u.id,name:u.name,email:u.email,role:u.role,workshopId:u.workshop_id,mustChangePassword:u.must_change_password,csrfToken:token}; res.redirect(u.must_change_password?'/password/change':'/'); }); } catch(e){next(e);} });
app.post('/logout', needAuth, (req,res)=>req.session.destroy(()=>res.redirect('/login')));
app.get('/superuser/login',(req,res)=>req.session.platformAdmin?res.redirect('/superuser'):res.send(page('Accesso superuser',`${takeFlash(req)}<section class="login-card card"><h2>Console GO</h2><form method="post" action="/superuser/login">${formToken(req)}${input('Utente','username','text','wincklers',true)}${input('Password','password','password','',true)}<button class="button primary">Accedi</button></form></section>`)));
app.post('/superuser/login',async(req,res,next)=>{try{const a=(await pool.query('SELECT id,username,password_hash FROM platform_admins WHERE lower(username)=lower($1) AND active=true',[req.body.username||''])).rows[0];if(!a||!await bcrypt.compare(req.body.password||'',a.password_hash)){flash(req,'Credenziali superuser non corrette.');return res.redirect('/superuser/login');}await pool.query('UPDATE platform_admins SET last_login_at=now() WHERE id=$1',[a.id]);req.session.regenerate(err=>{if(err)return next(err);const token=crypto.randomBytes(24).toString('hex');req.session.csrf=token;req.session.platformAdmin={id:a.id,username:a.username,csrfToken:token};res.redirect('/superuser');});}catch(e){next(e);}});
app.post('/superuser/logout',needSuperuser,(req,res)=>req.session.destroy(()=>res.redirect('/superuser/login')));
const superPage=(req,title,body,active='dashboard')=>page(title,body,{name:req.session.platformAdmin.username,role:'superuser',csrfToken:csrf(req)},active);
app.get('/superuser',needSuperuser,async(req,res,next)=>{try{const [shops,pending]=await Promise.all([pool.query(`SELECT w.id,w.name,w.status,w.created_at,l.expires_at,(SELECT count(*)::int FROM users u WHERE u.workshop_id=w.id AND u.active) AS active_users FROM workshops w LEFT JOIN LATERAL (SELECT expires_at FROM licenses WHERE workshop_id=w.id ORDER BY created_at DESC LIMIT 1) l ON true ORDER BY w.id`),pool.query("SELECT count(*)::int AS n FROM registration_requests WHERE status='pending'")]);const rows=shops.rows.map(w=>`<tr><td><a href="/superuser/workshops/${w.id}">${esc(w.name)}</a></td><td><span class="badge">${esc(w.status)}</span></td><td>${Number(w.active_users)}</td><td>${w.expires_at?new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeZone:'Europe/Rome'}).format(new Date(w.expires_at)):'—'}</td><td><a class="button small" href="/superuser/workshops/${w.id}">Apri</a></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessuna officina</td></tr>';res.send(superPage(req,'Console superuser',`${takeFlash(req)}<section class="card"><div class="section-heading"><p>Officine registrate · richieste in attesa: <strong>${pending.rows[0].n}</strong></p><a class="button primary" href="/superuser/workshops/new">Crea officina</a><a class="button" href="/superuser/registrations">Richieste</a></div><div class="table-wrap"><table><thead><tr><th>Officina</th><th>Stato</th><th>Utenti attivi</th><th>Licenza fino al</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`));}catch(e){next(e);}});
app.get('/superuser/registrations',needSuperuser,async(req,res,next)=>{try{const r=await pool.query('SELECT * FROM registration_requests ORDER BY submitted_at DESC');const rows=r.rows.map(x=>`<tr><td>${esc(x.workshop_name)}</td><td>${esc(x.owner_name)}<br>${esc(x.email)}</td><td>${esc(x.phone||'—')}</td><td>${esc(x.status)}</td><td>${fmtDate(x.submitted_at)}</td><td>${x.status==='pending'?`<form method="post" action="/superuser/registrations/${x.id}/approve">${formToken(req)}${select('Licenza','months',[[1,'1 mese'],[3,'3 mesi'],[6,'6 mesi'],[12,'12 mesi'],[24,'24 mesi']],'12')}<button class="button small primary">Approva</button></form><form method="post" action="/superuser/registrations/${x.id}/decline">${formToken(req)}<button class="button small">Declina</button></form>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nessuna richiesta</td></tr>';res.send(superPage(req,'Richieste officina',`${takeFlash(req)}<section class="card"><div class="table-wrap"><table><thead><tr><th>Officina</th><th>Titolare</th><th>Telefono</th><th>Stato</th><th>Invio</th><th>Decisione</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,'bookings'));}catch(e){next(e);}});
app.get('/superuser/workshops/new',needSuperuser,(req,res)=>res.send(superPage(req,'Crea officina',`${takeFlash(req)}<section class="card"><form method="post" action="/superuser/workshops"><div class="form-grid">${formToken(req)}${input('Nome officina','workshop_name','text','',true)}${input('Nome titolare','owner_name','text','',true)}${input('Email titolare','email','email','',true)}${input('Telefono','phone')}${input('Password iniziale (almeno 12 caratteri)','password','password','',true)}${select('Durata licenza','months',[[1,'1 mese'],[3,'3 mesi'],[6,'6 mesi'],[12,'12 mesi'],[24,'24 mesi']],'12')}</div><button class="button primary">Crea officina</button></form></section>`)));
app.post('/superuser/workshops',needSuperuser,async(req,res,next)=>{const c=await pool.connect();try{const name=String(req.body.workshop_name||'').trim(),owner=String(req.body.owner_name||'').trim(),email=String(req.body.email||'').trim().toLowerCase(),password=String(req.body.password||''),months=Number(req.body.months);if(!name||!owner||!email.includes('@')||password.length<12||![1,3,6,12,24].includes(months))throw new Error('Controlla i dati e usa una password di almeno 12 caratteri.');const hash=await bcrypt.hash(password,12);await c.query('BEGIN');const w=(await c.query("INSERT INTO workshops(name,status) VALUES($1,'active') RETURNING id",[name])).rows[0];const u=(await c.query("INSERT INTO users(name,email,password_hash,role,workshop_id,must_change_password) VALUES($1,$2,$3,'owner',$4,true) RETURNING id",[owner,email,hash,w.id])).rows[0];await c.query('INSERT INTO workshop_settings(id,workshop_id,business_name,phone,email) VALUES(1,$1,$2,$3,$4)',[w.id,name,req.body.phone||'',email]);await c.query("INSERT INTO licenses(workshop_id,expires_at,status,created_by) VALUES($1,now()+($2||' months')::interval,'active',$3)",[w.id,months,req.session.platformAdmin.id]);await c.query("INSERT INTO audit_log(workshop_id,user_id,action,entity_type,entity_id,details) VALUES($1,$2,'create','workshop',$3,$4)",[w.id,u.id,String(w.id),JSON.stringify({created_by:req.session.platformAdmin.username})]);await c.query('COMMIT');flash(req,'Officina creata. Il titolare dovrà cambiare la password al primo accesso.');res.redirect(`/superuser/workshops/${w.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.code==='23505'?'Esiste già un account con questa email.':e.message);res.redirect('/superuser/workshops/new');}finally{c.release();}});
app.get('/superuser/workshops/:id/logo',needSuperuser,async(req,res,next)=>{try{const r=await pool.query('SELECT logo_data,logo_mime,logo_path FROM workshop_settings WHERE workshop_id=$1 AND id=1',[req.params.id]);if(!r.rows[0]?.logo_data)return res.sendFile(path.resolve(__dirname,'../assets/brand/go-logo.png'));res.setHeader('Cache-Control','private, max-age=300');res.type(r.rows[0].logo_mime).send(r.rows[0].logo_data);}catch(e){next(e);}});
app.get('/superuser/workshops/:id',needSuperuser,async(req,res,next)=>{try{const [w,u,s,l]=await Promise.all([pool.query('SELECT * FROM workshops WHERE id=$1',[req.params.id]),pool.query('SELECT id,name,email,role,active,last_login_at,must_change_password FROM users WHERE workshop_id=$1 ORDER BY name',[req.params.id]),pool.query('SELECT * FROM workshop_settings WHERE workshop_id=$1 AND id=1',[req.params.id]),pool.query('SELECT * FROM licenses WHERE workshop_id=$1 ORDER BY created_at DESC',[req.params.id])]);if(!w.rowCount)return res.sendStatus(404);const cfg=s.rows[0]||{},userRows=u.rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${esc(x.role)}</td><td>${x.last_login_at?new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Rome'}).format(new Date(x.last_login_at)):'Mai'}</td><td>${x.active?'Attivo':'Disattivato'}</td><td><form method="post" action="/superuser/users/${x.id}/reset-password">${formToken(req)}<input type="hidden" name="workshop_id" value="${req.params.id}">${input('Password temporanea','password','password','',true)}<button class="button small">Reimposta</button></form></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nessun utente</td></tr>';const licenses=l.rows.map(x=>`<tr><td>${fmtDate(x.starts_at)}</td><td>${fmtDate(x.expires_at)}</td><td>${esc(x.status)}</td></tr>`).join('');res.send(superPage(req,w.rows[0].name,`${takeFlash(req)}<section class="card"><div class="detail-grid"><div><span class="muted">Stato officina</span><strong>${esc(w.rows[0].status)}</strong></div><div><span class="muted">Ragione sociale</span><strong>${esc(cfg.business_name||'—')}</strong></div><div><span class="muted">Indirizzo</span><strong>${esc(cfg.address||'—')}</strong></div><div><span class="muted">Contatti</span><strong>${esc(cfg.phone||'—')} · ${esc(cfg.email||'—')}</strong></div><div><span class="muted">P.IVA / C.F.</span><strong>${esc(cfg.vat_number||'—')} / ${esc(cfg.tax_code||'—')}</strong></div><div><span class="muted">Tariffa oraria</span><strong>${money(cfg.hourly_rate)}</strong></div></div><form class="inline-form" method="post" action="/superuser/workshops/${req.params.id}/license">${formToken(req)}${select('Estendi licenza','months',[[1,'1 mese'],[3,'3 mesi'],[6,'6 mesi'],[12,'12 mesi'],[24,'24 mesi']],'12')}<button class="button primary">Estendi</button></form><form method="post" action="/superuser/workshops/${req.params.id}/status">${formToken(req)}<button class="button">${w.rows[0].status==='suspended'?'Riattiva officina':'Sospendi officina'}</button></form></section><section class="card"><h2>Licenze</h2><div class="table-wrap"><table><thead><tr><th>Inizio</th><th>Scadenza</th><th>Stato</th></tr></thead><tbody>${licenses}</tbody></table></div></section><section class="card"><h2>Utenti e accessi</h2><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Email</th><th>Ruolo</th><th>Ultimo accesso</th><th>Stato</th><th>Reset password</th></tr></thead><tbody>${userRows}</tbody></table></div></section>`,''));}catch(e){next(e);}});
app.post('/superuser/registrations/:id/approve',needSuperuser,async(req,res,next)=>{const c=await pool.connect();try{const months=Number(req.body.months);if(![1,3,6,12,24].includes(months))throw new Error('Durata licenza non valida.');await c.query('BEGIN');const r=await c.query("SELECT * FROM registration_requests WHERE id=$1 AND status='pending' FOR UPDATE",[req.params.id]);if(!r.rowCount)throw new Error('La richiesta non è più in attesa.');const x=r.rows[0],w=(await c.query("INSERT INTO workshops(name,status) VALUES($1,'active') RETURNING id",[x.workshop_name])).rows[0],u=(await c.query("INSERT INTO users(name,email,password_hash,role,workshop_id,must_change_password) VALUES($1,$2,$3,'owner',$4,true) RETURNING id",[x.owner_name,x.email,x.password_hash,w.id])).rows[0];await c.query('INSERT INTO workshop_settings(id,workshop_id,business_name,phone,email) VALUES(1,$1,$2,$3,$4)',[w.id,x.workshop_name,x.phone,x.email]);await c.query("INSERT INTO licenses(workshop_id,expires_at,status,created_by) VALUES($1,now()+($2||' months')::interval,'active',$3)",[w.id,months,req.session.platformAdmin.id]);await c.query("UPDATE registration_requests SET status='approved',reviewed_at=now(),reviewed_by=$1 WHERE id=$2",[req.session.platformAdmin.id,x.id]);await c.query("INSERT INTO audit_log(workshop_id,user_id,action,entity_type,entity_id,details) VALUES($1,$2,'approve','registration_request',$3,$4)",[w.id,u.id,String(x.id),JSON.stringify({created_by:req.session.platformAdmin.username,license_months:months})]);await c.query('COMMIT');flash(req,`Richiesta approvata; officina ${x.workshop_name} attivata.`);res.redirect('/superuser/registrations');}catch(e){await c.query('ROLLBACK');flash(req,e.code==='23505'?'L’email è già associata a un utente.':e.message);res.redirect('/superuser/registrations');}finally{c.release();}});
app.post('/superuser/registrations/:id/decline',needSuperuser,async(req,res,next)=>{try{const r=await pool.query("UPDATE registration_requests SET status='declined',reviewed_at=now(),reviewed_by=$1,review_note=$2 WHERE id=$3 AND status='pending' RETURNING id",[req.session.platformAdmin.id,String(req.body.note||'').slice(0,500),req.params.id]);flash(req,r.rowCount?'Richiesta declinata.':'La richiesta non è più in attesa.');res.redirect('/superuser/registrations');}catch(e){next(e);}});
app.post('/superuser/workshops/:id/license',needSuperuser,async(req,res,next)=>{try{const months=Number(req.body.months);if(![1,3,6,12,24].includes(months))throw new Error('Durata licenza non valida.');await pool.query("INSERT INTO licenses(workshop_id,starts_at,expires_at,status,created_by) SELECT $1,anchor,anchor+($2||' months')::interval,'active',$3 FROM (SELECT greatest(now(),coalesce(max(expires_at),now())) AS anchor FROM licenses WHERE workshop_id=$1 AND status='active') a",[req.params.id,months,req.session.platformAdmin.id]);flash(req,'Licenza estesa.');res.redirect(`/superuser/workshops/${req.params.id}`);}catch(e){next(e);}});
app.post('/superuser/workshops/:id/status',needSuperuser,async(req,res,next)=>{try{await pool.query("UPDATE workshops SET status=CASE WHEN status='suspended' THEN 'active' ELSE 'suspended' END WHERE id=$1",[req.params.id]);flash(req,'Stato officina aggiornato.');res.redirect(`/superuser/workshops/${req.params.id}`);}catch(e){next(e);}});
app.post('/superuser/users/:id/reset-password',needSuperuser,async(req,res,next)=>{try{const password=String(req.body.password||'');if(password.length<12)throw new Error('La password temporanea deve contenere almeno 12 caratteri.');const hash=await bcrypt.hash(password,12);const r=await pool.query('UPDATE users SET password_hash=$1,must_change_password=true WHERE id=$2 AND workshop_id=$3 RETURNING id',[hash,req.params.id,req.body.workshop_id]);if(!r.rowCount)throw new Error('Utente non trovato in questa officina.');await pool.query("DELETE FROM user_sessions WHERE sess->'user'->>'id'=$1",[String(req.params.id)]);flash(req,'Password temporanea impostata. L’utente dovrà cambiarla al prossimo accesso.');res.redirect(`/superuser/workshops/${req.body.workshop_id}`);}catch(e){flash(req,e.message);res.redirect(`/superuser/workshops/${req.body.workshop_id||''}`);}});

app.get('/', needAuth, async (req,res,next)=>{ try {
  const [orders, bookings, timers, stock] = await Promise.all([
    pool.query(`SELECT w.id,w.status,w.target_date,v.plate,v.make,v.model,c.name AS customer FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id WHERE w.status NOT IN ('closed','cancelled') ORDER BY w.created_at DESC LIMIT 8`),
    pool.query(`SELECT b.id,b.starts_at,b.reason,v.plate,c.name AS customer FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id JOIN customers c ON c.id=b.customer_id WHERE b.starts_at >= now()-interval '1 day' AND b.status NOT IN ('cancelled','completed') ORDER BY b.starts_at LIMIT 6`),
    pool.query(`SELECT t.id,t.started_at,t.paused_at,t.pause_seconds,u.name AS mechanic,o.title,w.id AS order_id,v.plate FROM time_entries t JOIN users u ON u.id=t.user_id JOIN work_operations o ON o.id=t.operation_id JOIN work_orders w ON w.id=o.work_order_id JOIN vehicles v ON v.id=w.vehicle_id WHERE t.stopped_at IS NULL ORDER BY t.started_at`),
    pool.query(`SELECT count(*)::int AS count FROM inventory_items WHERE quantity<=minimum_quantity`)
  ]);
  const orderRows=orders.rows.map(x=>`<tr><td><a href="/work-orders/${x.id}">GO-${x.id}</a></td><td>${esc(x.plate)} · ${esc(x.make)} ${esc(x.model)}</td><td>${esc(x.customer)}</td><td><span class="badge">${esc(statuses[x.status]||x.status)}</span></td><td>${fmtDate(x.target_date)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun ordine aperto</td></tr>';
  const bookingRows=bookings.rows.map(x=>`<tr><td>${new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Rome'}).format(new Date(x.starts_at))}</td><td>${esc(x.plate)}</td><td>${esc(x.customer)}</td><td>${esc(x.reason)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun appuntamento imminente</td></tr>';
  const timerCards=timers.rows.map(x=>`<div class="timer-row"><div><strong>${esc(x.mechanic)} ${x.paused_at?'<span class="badge warning">In pausa</span>':'<span class="badge good">Attivo</span>'}</strong><span>${esc(x.plate)} · ${esc(x.title)}</span></div><span class="live-timer" data-start="${new Date(x.started_at).getTime()}" data-paused="${x.paused_at?new Date(x.paused_at).getTime():''}" data-pause-seconds="${Number(x.pause_seconds)}">00:00:00</span></div>`).join('')||'<p class="empty">Nessun timer attivo o in pausa</p>';
  const body=`${takeFlash(req)}<section class="stats"><article class="stat card"><span>Ordini aperti</span><strong>${orders.rowCount}</strong></article><article class="stat card"><span>Appuntamenti</span><strong>${bookings.rowCount}</strong></article><article class="stat card"><span>Timer attivi</span><strong>${timers.rowCount}</strong></article><article class="stat card"><span>Articoli da riordinare</span><strong>${stock.rows[0].count}</strong></article></section><div class="grid-two"><section class="card"><div class="section-heading"><h2>Vetture in officina</h2><a class="button small" href="/work-orders/new">Nuovo ordine</a></div><div class="table-wrap"><table><thead><tr><th>Ordine</th><th>Veicolo</th><th>Cliente</th><th>Stato</th><th>Obiettivo</th></tr></thead><tbody>${orderRows}</tbody></table></div></section><section class="card"><div class="section-heading"><h2>Timer in corso</h2></div>${timerCards}<h2 class="subhead">Prossimi appuntamenti</h2><div class="table-wrap"><table><thead><tr><th>Quando</th><th>Targa</th><th>Cliente</th><th>Motivo</th></tr></thead><tbody>${bookingRows}</tbody></table></div></section></div>`;
  res.send(page('Panoramica',body,req.session.user,'dashboard'));
} catch(e){next(e);} });

app.get('/customers', needAuth, async (req,res,next)=>{ try { const q=(req.query.q||'').trim(); const r=await pool.query(`SELECT * FROM customers WHERE ($1='' OR name ILIKE '%'||$1||'%' OR phone ILIKE '%'||$1||'%' OR email ILIKE '%'||$1||'%') ORDER BY name LIMIT 200`,[q]); const rows=r.rows.map(c=>`<tr><td><a href="/customers/${c.id}">${esc(c.name)}</a></td><td>${esc(c.phone)}</td><td>${esc(c.email)}</td><td>${esc(c.vat_number||c.tax_code)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun cliente registrato</td></tr>'; res.send(page('Clienti',`${takeFlash(req)}<section class="card"><div class="section-heading"><form class="inline-form"><input name="q" placeholder="Cerca cliente, telefono o email" value="${esc(q)}"><button class="button">Cerca</button></form><a class="button primary" href="/customers/new">Nuovo cliente</a></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Telefono</th><th>Email</th><th>CF / P. IVA</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'customers')); }catch(e){next(e);} });
app.get('/customers/new',needAuth,(req,res)=>res.send(page('Nuovo cliente',`<section class="card"><form method="post" action="/customers">${formToken(req)}<div class="form-grid">${select('Tipo','kind',[['person','Persona'],['business','Azienda']])}${input('Nome o ragione sociale','name','text','',true)}${input('Codice fiscale','tax_code')}${input('Partita IVA','vat_number')}${input('Email','email','email')}${input('Telefono','phone','tel')}${input('Indirizzo','address')}</div><label>Note<textarea name="notes"></textarea></label><button class="button primary">Salva cliente</button></form></section>`,req.session.user,'customers')));
app.post('/customers',needAuth,async(req,res,next)=>{try{const r=await pool.query(`INSERT INTO customers(kind,name,tax_code,vat_number,email,phone,address,notes) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id`,[req.body.kind,req.body.name,req.body.tax_code||'',req.body.vat_number||'',req.body.email||'',req.body.phone||'',req.body.address||'',req.body.notes||'']); await pool.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'create','customer',String(r.rows[0].id)]); flash(req,'Cliente creato.');res.redirect(`/customers/${r.rows[0].id}`);}catch(e){next(e);}});
app.get('/customers/:id',needAuth,async(req,res,next)=>{try{const c=(await pool.query('SELECT * FROM customers WHERE id=$1',[req.params.id])).rows[0];if(!c)return res.sendStatus(404);const vs=await pool.query('SELECT * FROM vehicles WHERE customer_id=$1 ORDER BY plate',[c.id]);const rows=vs.rows.map(v=>`<tr><td><a href="/vehicles/${v.id}">${esc(v.plate)}</a></td><td>${esc(v.make)} ${esc(v.model)}</td><td>${v.mileage.toLocaleString('it-IT')} km</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Nessun veicolo associato</td></tr>';res.send(page(c.name,`${takeFlash(req)}<section class="card"><div class="detail-grid"><div><span class="muted">Telefono</span><strong>${esc(c.phone||'—')}</strong></div><div><span class="muted">Email</span><strong>${esc(c.email||'—')}</strong></div><div><span class="muted">Indirizzo</span><strong>${esc(c.address||'—')}</strong></div></div><div class="section-heading"><h2>Veicoli</h2><div class="actions"><form method="post" action="/customers/${c.id}/portal-link">${formToken(req)}<button class="button">Crea link portale</button></form><a class="button" href="/customers/${c.id}/export.json">Esporta dati cliente</a><a class="button primary" href="/vehicles/new?customer_id=${c.id}">Aggiungi veicolo</a></div></div><div class="table-wrap"><table><thead><tr><th>Targa</th><th>Veicolo</th><th>Chilometraggio</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'customers'));}catch(e){next(e);}});
app.post('/customers/:id/portal-link',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{try{const c=await pool.query('SELECT id FROM customers WHERE id=$1',[req.params.id]);if(!c.rowCount)return res.sendStatus(404);const token=crypto.randomBytes(32).toString('base64url'),hash=crypto.createHash('sha256').update(token).digest('hex'),expires=new Date(Date.now()+90*86400000);const created=await pool.query('INSERT INTO customer_portal_tokens(customer_id,token_hash,expires_at,created_by) VALUES($1,$2,$3,$4) RETURNING id',[req.params.id,hash,expires,req.session.user.id]);await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'create_customer_portal_link','customer',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({expires_at:expires.toISOString()})]);const url=`${req.protocol}://${req.get('host')}/customer/portal/${token}`;res.send(page('Link portale cliente',`<section class="card"><h2>Accesso al portale pronto</h2><p>Il link mostra solo veicoli e stato degli interventi. Scade il ${fmtDate(expires)}. Copialo e condividilo tramite un canale concordato con il cliente.</p><label>Link<input id="customer-portal-link" readonly value="${esc(url)}"></label><button class="button primary" type="button" data-copy="#customer-portal-link">Copia link</button><form class="inline-form" method="post" action="/customer-portal-tokens/${created.rows[0].id}/revoke">${formToken(req)}<button class="button">Revoca link</button></form><p><a href="/customers/${req.params.id}">Torna alla scheda cliente</a></p></section>`,req.session.user,'customers'));}catch(e){next(e);}});
app.post('/customer-portal-tokens/:id/revoke',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{try{const r=await pool.query('UPDATE customer_portal_tokens SET revoked_at=now() WHERE id=$1 AND revoked_at IS NULL RETURNING customer_id',[req.params.id]);if(!r.rowCount)throw new Error('Link non trovato o già revocato.');await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,'revoke_customer_portal_link','customer',$2)`,[req.session.user.id,String(r.rows[0].customer_id)]);flash(req,'Link portale revocato.');res.redirect(`/customers/${r.rows[0].customer_id}`);}catch(e){flash(req,e.message);res.redirect('/customers');}});
app.get('/customers/:id/export.json',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{try{const customer=await pool.query('SELECT id,kind,name,tax_code,vat_number,email,phone,address,notes,created_at FROM customers WHERE id=$1',[req.params.id]);if(!customer.rowCount)return res.sendStatus(404);const [vehicles,orders,acceptances]=await Promise.all([pool.query('SELECT id,plate,vin,make,model,year,fuel,mileage,created_at FROM vehicles WHERE customer_id=$1 ORDER BY id',[req.params.id]),pool.query(`SELECT id,vehicle_id,status,complaint,mileage_in,target_date,created_at,updated_at FROM work_orders WHERE customer_id=$1 ORDER BY id`,[req.params.id]),pool.query(`SELECT document_type,document_version,accepted,accepted_by,accepted_at FROM document_acceptances WHERE customer_id=$1 ORDER BY accepted_at`,[req.params.id])]);await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'export_customer_data','customer',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({format:'json'})]);res.type('application/json').set('Content-Disposition',`attachment; filename="cliente-${req.params.id}-dati.json"`).send(JSON.stringify({exported_at:new Date().toISOString(),customer:customer.rows[0],vehicles:vehicles.rows,work_orders:orders.rows,document_acceptances:acceptances.rows},null,2));}catch(e){next(e);}});

