app.post('/work-orders',needAuth,async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const v=await c.query('SELECT customer_id FROM vehicles WHERE id=$1',[req.body.vehicle_id]);if(!v.rowCount)throw new Error('Seleziona un veicolo valido');const r=await c.query(`INSERT INTO work_orders(customer_id,vehicle_id,status,complaint,mileage_in,fuel_level,target_date,notes,created_by) VALUES($1,$2,'checked_in',$3,$4,$5,$6,$7,$8) RETURNING id`,[v.rows[0].customer_id,req.body.vehicle_id,req.body.complaint,req.body.mileage_in||0,req.body.fuel_level||'',req.body.target_date||null,req.body.notes||'',req.session.user.id]);await c.query(`INSERT INTO work_operations(work_order_id,title) VALUES($1,'Diagnosi iniziale')`,[r.rows[0].id]);await c.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'create','work_order',String(r.rows[0].id)]);await c.query('COMMIT');flash(req,'Ordine di lavoro creato.');res.redirect(`/work-orders/${r.rows[0].id}`);}catch(e){await c.query('ROLLBACK');next(e);}finally{c.release();}});
app.get('/work-orders/:id',needAuth,async(req,res,next)=>{
  try {
    const r=await pool.query(`SELECT w.*,v.plate,v.make,v.model,v.vin,c.name AS customer FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id WHERE w.id=$1`,[req.params.id]);
    if(!r.rowCount)return res.sendStatus(404);
    const w=r.rows[0];
    const [ops,mechanics,estimate,checks,roadTests,photos,templates,acceptances,parts]=await Promise.all([
      pool.query(`SELECT o.*,coalesce(sum(coalesce(t.adjusted_seconds,CASE WHEN t.paused_at IS NOT NULL THEN extract(epoch from t.paused_at-t.started_at)-t.pause_seconds WHEN t.stopped_at IS NULL THEN extract(epoch from now()-t.started_at)-t.pause_seconds ELSE extract(epoch from t.stopped_at-t.started_at)-t.pause_seconds END)),0)::int AS person_seconds,coalesce(sum(CASE WHEN t.billable THEN coalesce(t.adjusted_seconds,CASE WHEN t.paused_at IS NOT NULL THEN extract(epoch from t.paused_at-t.started_at)-t.pause_seconds WHEN t.stopped_at IS NULL THEN extract(epoch from now()-t.started_at)-t.pause_seconds ELSE extract(epoch from t.stopped_at-t.started_at)-t.pause_seconds END) ELSE 0 END),0)::int AS billable_seconds,coalesce(sum(coalesce(t.adjusted_seconds,CASE WHEN t.paused_at IS NOT NULL THEN extract(epoch from t.paused_at-t.started_at)-t.pause_seconds WHEN t.stopped_at IS NULL THEN extract(epoch from now()-t.started_at)-t.pause_seconds ELSE extract(epoch from t.stopped_at-t.started_at)-t.pause_seconds END)*t.internal_cost_rate/3600),0)::numeric AS internal_cost,coalesce(sum(CASE WHEN t.billable THEN coalesce(t.adjusted_seconds,CASE WHEN t.paused_at IS NOT NULL THEN extract(epoch from t.paused_at-t.started_at)-t.pause_seconds WHEN t.stopped_at IS NULL THEN extract(epoch from now()-t.started_at)-t.pause_seconds ELSE extract(epoch from t.stopped_at-t.started_at)-t.pause_seconds END)*t.bill_rate/3600 ELSE 0 END),0)::numeric AS billable_value,coalesce(extract(epoch from max(coalesce(t.stopped_at,t.paused_at,now()))-min(t.started_at)),0)::int AS elapsed_seconds FROM work_operations o LEFT JOIN time_entries t ON t.operation_id=o.id WHERE o.work_order_id=$1 GROUP BY o.id ORDER BY o.id`,[w.id]),
      pool.query(`SELECT id,name FROM users WHERE active=true AND role='mechanic' ORDER BY name`),
      pool.query(`SELECT * FROM estimates WHERE work_order_id=$1 ORDER BY version DESC LIMIT 1`,[w.id]),
      pool.query(`SELECT * FROM quality_checks WHERE work_order_id=$1 ORDER BY id`,[w.id]),
      pool.query(`SELECT * FROM road_tests WHERE work_order_id=$1 ORDER BY tested_at DESC LIMIT 5`,[w.id]),
      pool.query(`SELECT id,file_name,mime_type,created_at FROM documents WHERE work_order_id=$1 AND document_type='vehicle_photo' ORDER BY created_at DESC`,[w.id]),
      pool.query('SELECT repair_terms,privacy_notice FROM workshop_settings WHERE id=1'),
      pool.query('SELECT * FROM document_acceptances WHERE work_order_id=$1 ORDER BY accepted_at DESC',[w.id]),
      pool.query(`SELECT r.*,i.sku,i.description FROM inventory_reservations r JOIN inventory_items i ON i.id=r.item_id WHERE r.work_order_id=$1 ORDER BY r.created_at DESC`,[w.id])
    ]);
    const opRows=await Promise.all(ops.rows.map(async o=>{
      const [assignees,activeTimer,entries]=await Promise.all([
        pool.query('SELECT user_id FROM operation_assignments WHERE operation_id=$1',[o.id]),
        pool.query('SELECT paused_at FROM time_entries WHERE operation_id=$1 AND user_id=$2 AND stopped_at IS NULL',[o.id,req.session.user.id]),
        pool.query(`SELECT t.id,t.user_id,u.name,t.started_at,t.stopped_at,t.paused_at,t.pause_seconds,t.adjusted_seconds,t.billable,t.bill_rate,t.internal_cost_rate,coalesce(t.adjusted_seconds,extract(epoch from coalesce(t.stopped_at,t.paused_at,now())-t.started_at)-t.pause_seconds)::int AS seconds FROM time_entries t JOIN users u ON u.id=t.user_id WHERE t.operation_id=$1 ORDER BY t.started_at DESC LIMIT 30`,[o.id])
      ]);
      const selected=assignees.rows.map(a=>String(a.user_id));
      const timerAction=!activeTimer.rowCount?`<form method="post" action="/operations/${o.id}/timer/start">${formToken(req)}<button class="button small primary">Avvia</button></form>`:activeTimer.rows[0].paused_at?`<form method="post" action="/operations/${o.id}/timer/resume">${formToken(req)}<button class="button small">Riprendi</button></form>`:`<form method="post" action="/operations/${o.id}/timer/pause">${formToken(req)}<input name="reason" placeholder="Motivo pausa" aria-label="Motivo pausa" required><button class="button small">Pausa</button></form><form method="post" action="/operations/${o.id}/timer/stop">${formToken(req)}<button class="button small">Termina</button></form>`;
      const entryRows=entries.rows.map(t=>`<tr><td>${esc(t.name)}</td><td>${fmtDate(t.started_at)}${t.stopped_at?` · ${fmtDate(t.stopped_at)}`:t.paused_at?' · In pausa':' · Attivo'}</td><td>${Math.floor(Number(t.seconds)/3600)}h ${Math.floor((Number(t.seconds)%3600)/60)}m</td><td>${t.billable?'Sì':'No'}</td><td>${money(Number(t.seconds)*Number(t.bill_rate)/3600)}</td><td>${money(Number(t.seconds)*Number(t.internal_cost_rate)/3600)}</td><td>${['owner','admin','manager'].includes(req.session.user.role)&&t.stopped_at?`<form class="inline-form" method="post" action="/time-entries/${t.id}/correct">${formToken(req)}<input type="number" name="seconds" min="0" step="1" value="${Number(t.seconds)}" aria-label="Durata corretta in secondi" required><input name="reason" placeholder="Motivo rettifica" required><button class="button small">Rettifica</button></form>`:'—'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nessuna sessione timer registrata</td></tr>';
      return `<article class="operation"><div class="operation-head"><div><h3>${esc(o.title)}</h3><p class="muted">${esc(o.description||'Nessuna nota')}</p></div><span class="badge">${esc(o.status)}</span></div><div class="operation-actions"><span class="time-total">Ore persona: ${Math.floor(o.person_seconds/3600)}h ${Math.floor((o.person_seconds%3600)/60)}m · calendario: ${Math.floor(o.elapsed_seconds/3600)}h ${Math.floor((o.elapsed_seconds%3600)/60)}m · fatturabili: ${Math.floor(o.billable_seconds/3600)}h ${Math.floor((o.billable_seconds%3600)/60)}m</span>${timerAction}</div><p class="muted">Valore tempi fatturabili: ${money(o.billable_value)} · costo interno stimato: ${money(o.internal_cost)}. Il valore non viene aggiunto automaticamente alla fattura.</p><details><summary>Sessioni timer e rettifiche</summary><div class="table-wrap"><table><thead><tr><th>Meccanico</th><th>Periodo</th><th>Durata</th><th>Fatturabile</th><th>Valore</th><th>Costo interno</th><th>Rettifica</th></tr></thead><tbody>${entryRows}</tbody></table></div></details><form class="assign-form" method="post" action="/operations/${o.id}/assign">${formToken(req)}<label>Meccanici assegnati<select name="user_ids" multiple size="${Math.min(3,Math.max(1,mechanics.rowCount))}">${mechanics.rows.map(m=>`<option value="${m.id}" ${selected.includes(String(m.id))?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><button class="button small">Salva assegnazioni</button></form></article>`;
    }));
    const e=estimate.rows[0];
    const estimateBox=e?`<p>${e.estimate_type==='extra'?'Variazione / lavoro extra':'Preventivo iniziale'} · Versione ${e.version} · Stato: <span class="badge">${esc(e.status)}</span> · ${e.valid_until?`Valido fino al ${fmtDate(e.valid_until)}`:'Senza scadenza impostata'}</p><a class="button" href="/estimates/${e.id}/pdf">Scarica preventivo PDF</a>${e.status==='draft'||e.status==='sent'?`<form class="inline-form" method="post" action="/estimates/${e.id}/customer-link">${formToken(req)}<button class="button">Crea link cliente monouso</button></form>${['owner','admin','manager','reception'].includes(req.session.user.role)?`<form class="inline-form" method="post" action="/estimates/${e.id}/decision">${formToken(req)}<button class="button primary" name="decision" value="approved">Registra approvazione in officina</button><button class="button" name="decision" value="rejected">Registra rifiuto</button></form>`:''}`:''}`:'<p class="muted">Nessun preventivo ancora registrato.</p>';
    const eCurrent=estimate.rows[0];
    const latestTest=roadTests.rows[0];
    const qualityPassed=checks.rowCount>=6&&checks.rows.every(ch=>ch.passed===true)&&latestTest?.result==='passed';
    const readyAction=qualityPassed&&w.status!=='ready'&&w.status!=='delivered'&&w.status!=='closed'?`<form method="post" action="/work-orders/${w.id}/mark-ready">${formToken(req)}<button class="button primary">Conferma auto pronta</button></form>`:'';
    const createInvoice=eCurrent?.status==='approved'&&w.status==='ready'?`<form method="post" action="/work-orders/${w.id}/invoice">${formToken(req)}<button class="button primary">Prepara documento gestionale</button></form>`:'';
    const checkRows=checks.rows.map(ch=>`<tr><td>${esc(ch.label)}</td><td>${ch.passed===null?'<span class="badge warning">Da controllare</span>':ch.passed?'<span class="badge good">Superato</span>':'<span class="badge warning">Non superato</span>'}</td><td>${esc(ch.note||'—')}</td><td><form class="inline-form" method="post" action="/quality-checks/${ch.id}">${formToken(req)}<input type="hidden" name="work_order_id" value="${w.id}"><select name="passed" aria-label="Esito"><option value="true">Superato</option><option value="false">Non superato</option></select><input name="note" placeholder="Nota / anomalia"><button class="button small">Registra</button></form></td></tr>`).join('');
    const roadRows=roadTests.rows.map(t=>`<tr><td>${fmtDate(t.tested_at)}</td><td>${esc(t.result)}</td><td>${Number(t.mileage_start).toLocaleString('it-IT')} → ${t.mileage_end===null?'—':Number(t.mileage_end).toLocaleString('it-IT')} km</td><td>${esc(t.notes||'')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun test registrato</td></tr>';
    const photoRows=photos.rows.map(p=>`<a class="vehicle-photo" href="/work-orders/${w.id}/documents/${p.id}" target="_blank" rel="noopener"><img src="/work-orders/${w.id}/documents/${p.id}" alt="Foto veicolo ${esc(p.file_name)}"><span>${esc(p.file_name)}</span></a>`).join('')||'<p class="muted">Nessuna fotografia di presa in carico.</p>';
    const terms=templates.rows[0]||{repair_terms:'',privacy_notice:''};const termsVersion=crypto.createHash('sha256').update(terms.repair_terms).digest('hex');const privacyVersion=crypto.createHash('sha256').update(terms.privacy_notice).digest('hex');
    const acceptanceRows=acceptances.rows.map(a=>`<tr><td>${esc(a.document_type==='repair_terms'?'Condizioni di riparazione':'Informativa privacy')}</td><td>${esc(a.accepted_by)}</td><td>${fmtDate(a.accepted_at)}</td><td>${esc(a.document_version.slice(0,12))}…</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessuna presa visione registrata.</td></tr>';
    const partRows=parts.rows.map(p=>`<tr><td>${esc(p.sku||'')}</td><td><a href="/inventory/${p.item_id}">${esc(p.description)}</a></td><td>${Number(p.quantity)}</td><td>${esc(p.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun ricambio riservato a questo ordine.</td></tr>';
    const statusOpts=Object.entries(statuses).filter(([k])=>!['ready','invoiced','delivered','closed'].includes(k)).map(([k,v])=>[k,v]);
    const body=`${takeFlash(req)}<section class="card"><div class="section-heading"><div><span class="eyebrow">ORDINE GO-${w.id}</span><h2>${esc(w.plate)} · ${esc(w.make)} ${esc(w.model)}</h2><p class="muted">Cliente: ${esc(w.customer)} · VIN: ${esc(w.vin||'—')}</p></div><div class="actions"><a class="button" href="/work-orders/${w.id}/pdf">Genera / stampa scheda PDF</a><a class="button" href="/work-orders/${w.id}/documents">Archivio documenti</a></div></div><div class="detail-grid"><div><span class="muted">Ingresso</span><strong>${fmtDate(w.created_at)}</strong></div><div><span class="muted">Km ingresso</span><strong>${Number(w.mileage_in).toLocaleString('it-IT')}</strong></div><div><span class="muted">Stato</span><strong>${esc(statuses[w.status]||w.status)}</strong></div><div><span class="muted">Problema segnalato</span><strong>${esc(w.complaint)}</strong></div></div><form class="inline-form status-form" method="post" action="/work-orders/${w.id}/status">${formToken(req)}${select('Aggiorna stato','status',statusOpts,w.status)}<button class="button">Aggiorna stato</button></form></section><section class="card"><h2>Condizioni e informativa cliente</h2><p class="muted">La conferma viene registrata dall’operatore con nome, ora, versione e copia del testo mostrato; non equivale a una firma elettronica qualificata.</p><form method="post" action="/work-orders/${w.id}/acceptance">${formToken(req)}${input('Nome della persona che conferma','accepted_by','text','',true)}<input type="hidden" name="terms_version" value="${termsVersion}"><input type="hidden" name="privacy_version" value="${privacyVersion}"><label class="accept-row"><input type="checkbox" name="accept_terms" value="yes" ${terms.repair_terms?'':'disabled'}> Conferma ricezione e accettazione delle condizioni di riparazione${terms.repair_terms?'':' (testo non configurato)'}</label><details><summary>Condizioni applicabili</summary><p>${esc(terms.repair_terms||'Nessun testo configurato.')}</p></details><label class="accept-row"><input type="checkbox" name="ack_privacy" value="yes" ${terms.privacy_notice?'':'disabled'}> Conferma di aver ricevuto l’informativa privacy${terms.privacy_notice?'':' (testo non configurato)'}</label><details><summary>Informativa privacy</summary><p>${esc(terms.privacy_notice||'Nessun testo configurato.')}</p></details><button class="button">Registra presa visione</button></form><div class="table-wrap"><table><thead><tr><th>Documento</th><th>Persona</th><th>Data</th><th>Versione</th></tr></thead><tbody>${acceptanceRows}</tbody></table></div></section><section class="card"><div class="section-heading"><h2>Foto e documenti di presa in carico</h2></div><form class="inline-form photo-upload" method="post" action="/work-orders/${w.id}/photos" enctype="multipart/form-data">${formToken(req)}<label>Carica foto PNG/JPEG (massimo 8 file da 2 MB)<input name="photos" type="file" accept="image/png,image/jpeg" multiple required></label><button class="button">Salva foto</button></form><div class="photo-grid">${photoRows}</div></section><section class="card"><h2>Ricambi associati</h2><div class="table-wrap"><table><thead><tr><th>Codice</th><th>Articolo</th><th>Quantità</th><th>Stato</th></tr></thead><tbody>${partRows}</tbody></table></div></section><section class="card"><div class="section-heading"><h2>Lavorazioni e timer</h2></div>${opRows.join('')||'<p class="empty">Nessuna operazione</p>'}<form class="add-operation" method="post" action="/work-orders/${w.id}/operations">${formToken(req)}${input('Nuova operazione','title','text','',true)}${input('Descrizione','description')}<button class="button">Aggiungi operazione</button></form></section><section class="card"><div class="section-heading"><h2>Preventivo</h2><a class="button" href="/work-orders/${w.id}/estimate/new">Crea preventivo</a></div>${estimateBox}${createInvoice}</section><section class="card"><div class="section-heading"><h2>Controllo qualità</h2><form method="post" action="/work-orders/${w.id}/quality-checks/setup">${formToken(req)}<button class="button small">Prepara checklist</button></form></div><p class="muted">Tutte le verifiche e un test su strada superato sono necessari per segnare l’auto come pronta.</p><div class="table-wrap"><table><thead><tr><th>Controllo</th><th>Esito</th><th>Nota</th><th>Aggiorna</th></tr></thead><tbody>${checkRows||'<tr><td colspan="4" class="empty">Checklist non ancora preparata</td></tr>'}</tbody></table></div><form class="inline-form" method="post" action="/work-orders/${w.id}/road-tests">${formToken(req)}<input type="hidden" name="mileage_start" value="${Number(w.mileage_in)}">${input('Km dopo il test','mileage_end','number',String(Number(w.mileage_in)),true)}${select('Esito test','result',[['passed','Superato'],['failed','Non superato']])}${input('Esito e anomalie','notes')}<button class="button">Registra test</button></form><div class="table-wrap"><table><thead><tr><th>Data</th><th>Esito</th><th>Km</th><th>Note</th></tr></thead><tbody>${roadRows}</tbody></table></div>${readyAction}</section>`;
    res.send(page(`Ordine GO-${w.id}`,body,req.session.user,'orders'));
  } catch(e){next(e);}
});
app.post('/work-orders/:id/status',needAuth,allow('owner','admin','manager','mechanic'),async(req,res,next)=>{try{const target=req.body.status;if(!statuses[target]||['ready','invoiced','delivered','closed'].includes(target))throw new Error('Questo stato si raggiunge completando i controlli, il documento o la consegna dedicati.');const w=await pool.query('SELECT status FROM work_orders WHERE id=$1',[req.params.id]);if(!w.rowCount)return res.sendStatus(404);if(['scheduled','in_progress','quality_check','testing'].includes(target)){const approved=await pool.query(`SELECT 1 FROM estimates WHERE work_order_id=$1 AND status='approved' LIMIT 1`,[req.params.id]);if(!approved.rowCount)throw new Error('Prima di avviare la riparazione serve un preventivo approvato.');}await pool.query('UPDATE work_orders SET status=$1,updated_at=now() WHERE id=$2',[target,req.params.id]);await pool.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)',[req.session.user.id,'status_change','work_order',String(req.params.id),JSON.stringify({from:w.rows[0].status,to:target})]);flash(req,'Stato aggiornato.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}});
app.post('/work-orders/:id/quality-checks/setup',needAuth,allow('owner','admin','manager','mechanic'),async(req,res,next)=>{try{const w=await pool.query('SELECT id FROM work_orders WHERE id=$1',[req.params.id]);if(!w.rowCount)return res.sendStatus(404);const labels=['Serraggi verificati','Livelli controllati','Spie e anomalie verificate','Perdite assenti','Lavorazioni richieste completate','Area di lavoro e veicolo controllati'];for(const label of labels)await pool.query(`INSERT INTO quality_checks(work_order_id,label) SELECT $1,$2 WHERE NOT EXISTS (SELECT 1 FROM quality_checks WHERE work_order_id=$1 AND label=$2)`,[req.params.id,label]);flash(req,'Checklist controllo qualità pronta.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){next(e);}});
app.post('/work-orders/:id/photos',needAuth,allow('owner','admin','manager','reception','mechanic'),async(req,res,next)=>{const files=req.files||[];const c=await pool.connect();try{if(!files.length)throw new Error('Seleziona almeno una foto.');await c.query('BEGIN');const order=await c.query('SELECT id FROM work_orders WHERE id=$1 FOR UPDATE',[req.params.id]);if(!order.rowCount)throw new Error('Ordine di lavoro non trovato.');for(const f of files){const png=f.mimetype==='image/png'&&f.buffer.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));const jpeg=f.mimetype==='image/jpeg'&&f.buffer[0]===0xff&&f.buffer[1]===0xd8&&f.buffer[2]===0xff;if(!png&&!jpeg)throw new Error('Sono ammesse solo immagini PNG e JPEG valide.');const name=path.basename(f.originalname).slice(0,180)||'foto-veicolo';await c.query(`INSERT INTO documents(work_order_id,document_type,file_name,mime_type,file_data,created_by) VALUES($1,'vehicle_photo',$2,$3,$4,$5)`,[req.params.id,name,f.mimetype,f.buffer,req.session.user.id]);}await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'upload_photos','work_order',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({count:files.length})]);await c.query('COMMIT');flash(req,`${files.length} foto salvate nel database.`);res.redirect(`/work-orders/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}finally{c.release();}});
app.post('/work-orders/:id/acceptance',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{const c=await pool.connect();try{const name=String(req.body.accepted_by||'').trim();const acceptsTerms=req.body.accept_terms==='yes',ackPrivacy=req.body.ack_privacy==='yes';if(!name||(!acceptsTerms&&!ackPrivacy))throw new Error('Inserisci il nome e seleziona il documento confermato.');await c.query('BEGIN');const order=await c.query('SELECT id,customer_id FROM work_orders WHERE id=$1 FOR UPDATE',[req.params.id]);if(!order.rowCount)throw new Error('Ordine di lavoro non trovato.');const s=await c.query('SELECT repair_terms,privacy_notice FROM workshop_settings WHERE id=1');const templates=s.rows[0];const values=[['repair_terms',acceptsTerms?templates.repair_terms:null,req.body.terms_version],['privacy_notice',ackPrivacy?templates.privacy_notice:null,req.body.privacy_version]];for(const [type,content,postedVersion] of values){if(content===null)continue;if(!String(content||'').trim())throw new Error('Configura il testo del documento prima di registrare la presa visione.');const version=crypto.createHash('sha256').update(content).digest('hex');if(version!==postedVersion)throw new Error('I testi sono cambiati. Ricarica la scheda e verifica la versione corrente.');await c.query(`INSERT INTO document_acceptances(work_order_id,customer_id,document_type,document_version,accepted,accepted_by,evidence,user_id) VALUES($1,$2,$3,$4,true,$5,$6,$7)`,[req.params.id,order.rows[0].customer_id,type,version,name,JSON.stringify({method:'recorded_in_workshop_by_operator',text_snapshot:content}),req.session.user.id]);}await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'document_acceptance','work_order',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({repair_terms:acceptsTerms,privacy_notice:ackPrivacy})]);await c.query('COMMIT');flash(req,'Presa visione registrata con versione e copia del testo mostrato.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}finally{c.release();}});
app.get('/work-orders/:id/documents',needAuth,allow('owner','admin','manager','reception','mechanic'),async(req,res,next)=>{try{const order=await pool.query('SELECT id FROM work_orders WHERE id=$1',[req.params.id]);if(!order.rowCount)return res.sendStatus(404);const docs=await pool.query(`SELECT id,file_name,mime_type,document_type,created_at FROM documents WHERE work_order_id=$1 ORDER BY created_at DESC LIMIT 200`,[req.params.id]);const rows=docs.rows.map(d=>`<tr><td>${fmtDate(d.created_at)}</td><td>${esc(d.file_name)}</td><td>${esc(d.document_type)}</td><td><a class="button small" href="/work-orders/${req.params.id}/documents/${d.id}" target="_blank" rel="noopener">Apri / stampa</a></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun documento salvato</td></tr>';res.send(page(`Documenti · GO-${req.params.id}`,`<section class="card"><p>I PDF generati sono archiviati come copie e restano disponibili anche dopo modifiche successive ai dati o al logo.</p><div class="table-wrap"><table><thead><tr><th>Data copia</th><th>File</th><th>Tipo</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><p><a class="button" href="/work-orders/${req.params.id}">Torna all’ordine</a></p></section>`,req.session.user,'orders'));}catch(e){next(e);}});
app.get('/work-orders/:id/documents/:docid',needAuth,allow('owner','admin','manager','reception','mechanic'),async(req,res,next)=>{try{const d=await pool.query(`SELECT file_name,mime_type,file_data FROM documents WHERE id=$1 AND work_order_id=$2`,[req.params.docid,req.params.id]);if(!d.rowCount)return res.sendStatus(404);res.setHeader('Content-Disposition',`inline; filename="${d.rows[0].file_name.replace(/["\\\r\n]/g,'_')}"`);res.type(d.rows[0].mime_type).send(d.rows[0].file_data);}catch(e){next(e);}});
app.post('/quality-checks/:id',needAuth,allow('owner','admin','manager','mechanic'),async(req,res,next)=>{try{if(!['true','false'].includes(req.body.passed))throw new Error('Seleziona un esito valido.');const r=await pool.query(`UPDATE quality_checks SET passed=$1,note=$2,checked_by=$3,checked_at=now() WHERE id=$4 AND work_order_id=$5 RETURNING id`,[req.body.passed==='true',req.body.note||'',req.session.user.id,req.params.id,req.body.work_order_id]);if(!r.rowCount)return res.sendStatus(404);flash(req,'Controllo qualità registrato.');res.redirect(`/work-orders/${req.body.work_order_id}`);}catch(e){next(e);}});
app.post('/work-orders/:id/road-tests',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const start=Number(req.body.mileage_start),end=Number(req.body.mileage_end);if(!Number.isInteger(start)||!Number.isInteger(end)||end<start)throw new Error('I chilometri del test non sono validi.');if(!['passed','failed'].includes(req.body.result))throw new Error('Esito test non valido.');await pool.query(`INSERT INTO road_tests(work_order_id,driver_id,mileage_start,mileage_end,result,notes) VALUES($1,$2,$3,$4,$5,$6)`,[req.params.id,req.session.user.id,start,end,req.body.result,req.body.notes||'']);flash(req,'Test su strada registrato.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}});
app.post('/work-orders/:id/mark-ready',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const order=await pool.query(`SELECT status FROM work_orders WHERE id=$1`,[req.params.id]);if(!order.rowCount)return res.sendStatus(404);if(!['in_progress','quality_check','testing'].includes(order.rows[0].status))throw new Error('L’ordine non è in uno stato di controllo o test.');const checks=await pool.query('SELECT count(*)::int AS total,count(*) FILTER (WHERE passed IS TRUE)::int AS passed FROM quality_checks WHERE work_order_id=$1',[req.params.id]);const test=await pool.query('SELECT result FROM road_tests WHERE work_order_id=$1 ORDER BY tested_at DESC LIMIT 1',[req.params.id]);if(checks.rows[0].total<6||checks.rows[0].total!==checks.rows[0].passed||test.rows[0]?.result!=='passed')throw new Error('Completa tutti i controlli e registra un test superato prima di segnare l’auto pronta.');await pool.query(`UPDATE work_orders SET status='ready',updated_at=now() WHERE id=$1`,[req.params.id]);await pool.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'mark_ready','work_order',String(req.params.id)]);flash(req,'Veicolo segnato come pronto.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}});
app.post('/work-orders/:id/operations',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const title=String(req.body.title||'').trim();if(!title||title.length>180)throw new Error('Il titolo deve contenere da 1 a 180 caratteri.');await pool.query('INSERT INTO work_operations(work_order_id,title,description) VALUES($1,$2,$3)',[req.params.id,title,String(req.body.description||'').slice(0,2000)]);flash(req,'Operazione aggiunta.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}});
app.post('/operations/:id/timer/start',needAuth,allow('owner','admin','manager','mechanic'),async(req,res,next)=>{try{const op=await pool.query(`SELECT o.work_order_id,(o.id=(SELECT min(id) FROM work_operations WHERE work_order_id=o.work_order_id) AND o.title='Diagnosi iniziale') AS diagnosis_only FROM work_operations o WHERE o.id=$1`,[req.params.id]);if(!op.rowCount)return res.sendStatus(404);if(req.session.user.role==='mechanic'){const assigned=await pool.query('SELECT 1 FROM operation_assignments WHERE operation_id=$1 AND user_id=$2',[req.params.id,req.session.user.id]);if(!assigned.rowCount)throw new Error('Il timer è disponibile ai meccanici assegnati alla lavorazione.');}if(!op.rows[0].diagnosis_only){const approved=await pool.query(`SELECT 1 FROM estimates WHERE work_order_id=$1 AND status='approved' LIMIT 1`,[op.rows[0].work_order_id]);if(!approved.rowCount){flash(req,'Per avviare questa riparazione serve un preventivo approvato.');return res.redirect(req.get('Referrer')||'/work-orders');}}await pool.query(`INSERT INTO time_entries(operation_id,user_id,bill_rate,internal_cost_rate) SELECT $1,u.id,s.hourly_rate,u.internal_hourly_cost FROM users u CROSS JOIN workshop_settings s WHERE u.id=$2`,[req.params.id,req.session.user.id]);await pool.query(`UPDATE work_operations SET status='in_progress' WHERE id=$1`,[req.params.id]);if(!op.rows[0].diagnosis_only)await pool.query(`UPDATE work_orders SET status='in_progress',updated_at=now() WHERE id=$1`,[op.rows[0].work_order_id]);flash(req,'Timer avviato con tariffe registrate per questa sessione.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){if(e.code==='23505'){flash(req,'Hai già un timer attivo. Fermalo prima di iniziarne un altro.');return res.redirect(req.get('Referrer')||'/work-orders');}if(e.message.includes('timer è disponibile')){flash(req,e.message);return res.redirect(req.get('Referrer')||'/work-orders');}next(e);}});
app.post('/operations/:id/timer/pause',needAuth,async(req,res,next)=>{try{const reason=String(req.body.reason||'').trim();if(!reason)throw new Error('Indica il motivo della pausa.');const r=await pool.query(`UPDATE time_entries SET paused_at=now(),note=concat_ws(E'\\n',nullif(note,''),$3) WHERE operation_id=$1 AND user_id=$2 AND stopped_at IS NULL AND paused_at IS NULL RETURNING id`,[req.params.id,req.session.user.id,reason.slice(0,500)]);flash(req,r.rowCount?'Timer messo in pausa.':'Non hai un timer attivo da mettere in pausa.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){flash(req,e.message);res.redirect(req.get('Referrer')||'/work-orders');}});
app.post('/operations/:id/timer/resume',needAuth,async(req,res,next)=>{try{const r=await pool.query(`UPDATE time_entries SET pause_seconds=pause_seconds+extract(epoch from now()-paused_at)::int,paused_at=NULL WHERE operation_id=$1 AND user_id=$2 AND stopped_at IS NULL AND paused_at IS NOT NULL RETURNING id`,[req.params.id,req.session.user.id]);flash(req,r.rowCount?'Timer ripreso.':'Non hai un timer in pausa su questa operazione.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){next(e);}});
app.post('/operations/:id/timer/stop',needAuth,async(req,res,next)=>{try{const r=await pool.query(`UPDATE time_entries SET pause_seconds=pause_seconds+CASE WHEN paused_at IS NULL THEN 0 ELSE extract(epoch from now()-paused_at)::int END,paused_at=NULL,stopped_at=now() WHERE operation_id=$1 AND user_id=$2 AND stopped_at IS NULL RETURNING id`,[req.params.id,req.session.user.id]);flash(req,r.rowCount?'Timer terminato.':'Non hai un timer attivo su questa operazione.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){next(e);}});
app.post('/time-entries/:id/correct',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query(`SELECT t.*,o.work_order_id FROM time_entries t JOIN work_operations o ON o.id=t.operation_id WHERE t.id=$1 FOR UPDATE`,[req.params.id]);if(!q.rowCount)throw new Error('Sessione timer non trovata.');const t=q.rows[0];if(!t.stopped_at)throw new Error('Puoi rettificare solo una sessione terminata.');const seconds=Number(req.body.seconds),reason=String(req.body.reason||'').trim();if(!Number.isInteger(seconds)||seconds<0||seconds>86400||!reason)throw new Error('Indica una durata valida (0–24 ore) e il motivo della rettifica.');const original=Number(t.adjusted_seconds??(new Date(t.stopped_at)-new Date(t.started_at))/1000-Number(t.pause_seconds));await c.query(`INSERT INTO time_entry_adjustments(time_entry_id,original_seconds,corrected_seconds,original_billable,corrected_billable,reason,changed_by) VALUES($1,$2,$3,$4,$4,$5,$6)`,[t.id,Math.max(0,Math.round(original)),seconds,t.billable,reason.slice(0,500),req.session.user.id]);await c.query(`UPDATE time_entries SET adjusted_seconds=$1,correction_reason=concat_ws(E'\\n',nullif(correction_reason,''),$2) WHERE id=$3`,[seconds,reason.slice(0,500),t.id]);await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'correct_timer','time_entry',$2,$3)`,[req.session.user.id,String(t.id),JSON.stringify({original_seconds:original,corrected_seconds:seconds,reason})]);await c.query('COMMIT');flash(req,'Rettifica salvata; la registrazione originale resta nello storico.');res.redirect(`/work-orders/${t.work_order_id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(req.get('Referrer')||'/work-orders');}finally{c.release();}});
app.post('/operations/:id/assign',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const ids=Array.isArray(req.body.user_ids)?req.body.user_ids:req.body.user_ids?[req.body.user_ids]:[];if(ids.length){const valid=await c.query(`SELECT count(*)::int AS n FROM users WHERE id=ANY($1::bigint[]) AND role='mechanic' AND active=true`,[ids]);if(valid.rows[0].n!==ids.length)throw new Error('Puoi assegnare solo meccanici attivi.');}await c.query('DELETE FROM operation_assignments WHERE operation_id=$1',[req.params.id]);for(let i=0;i<ids.length;i++)await c.query('INSERT INTO operation_assignments(operation_id,user_id,is_lead) VALUES($1,$2,$3)',[req.params.id,ids[i],i===0]);await c.query('COMMIT');flash(req,'Assegnazioni aggiornate.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(req.get('Referrer')||'/work-orders');}finally{c.release();}});

app.get('/team',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const r=await pool.query('SELECT id,name,email,role,active,created_at FROM users ORDER BY name');const rows=r.rows.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${u.active?'<span class="badge good">Attivo</span>':'<span class="badge">Disattivato</span>'}</td><td>${fmtDate(u.created_at)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun utente</td></tr>';res.send(page('Utenti e meccanici',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Account individuali e ruoli del personale.</p><a class="button primary" href="/team/new">Aggiungi utente</a></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Email</th><th>Ruolo</th><th>Stato</th><th>Creato</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'team'));}catch(e){next(e);}});
app.get('/team/new',needAuth,allow('owner','admin'),(req,res)=>res.send(page('Nuovo utente',`<section class="card"><form method="post" action="/team">${formToken(req)}<div class="form-grid">${input('Nome','name','text','',true)}${input('Email','email','email','',true)}${input('Password iniziale (almeno 12 caratteri)','password','password','',true)}${select('Ruolo','role',[['manager','Responsabile officina'],['reception','Accettatore'],['mechanic','Meccanico'],['warehouse','Magazziniere'],['accounting','Amministrazione'],['accountant','Commercialista'],['admin','Amministratore']])}</div><button class="button primary">Crea account</button></form></section>`,req.session.user,'team')));
app.post('/team',needAuth,allow('owner','admin'),async(req,res,next)=>{try{if(String(req.body.password||'').length<12)throw new Error('La password iniziale deve contenere almeno 12 caratteri.');const allowed=['manager','reception','mechanic','warehouse','accounting','accountant','admin'];if(!allowed.includes(req.body.role))throw new Error('Ruolo non valido.');const hash=await bcrypt.hash(req.body.password,12);const r=await pool.query('INSERT INTO users(name,email,password_hash,role) VALUES($1,$2,$3,$4) RETURNING id',[req.body.name,req.body.email,hash,req.body.role]);await pool.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'create','user',String(r.rows[0].id)]);flash(req,'Utente creato.');res.redirect('/team');}catch(e){if(e.code==='23505'){flash(req,'Esiste già un account con questa email.');return res.redirect('/team/new');}if(e.message.includes('password')||e.message.includes('Ruolo')){flash(req,e.message);return res.redirect('/team/new');}next(e);}});

app.get('/work-orders/:id/estimate/new',needAuth,async(req,res,next)=>{try{const w=await pool.query('SELECT id FROM work_orders WHERE id=$1',[req.params.id]);if(!w.rowCount)return res.sendStatus(404);const s=(await pool.query('SELECT hourly_rate FROM workshop_settings WHERE id=1')).rows[0];res.send(page(`Nuovo preventivo · GO-${req.params.id}`,`<section class="card"><p class="muted">Ogni revisione resta nello storico. Se è un lavoro aggiuntivo, seleziona la variazione: non dovrà essere avviata prima della relativa approvazione.</p><form method="post" action="/work-orders/${req.params.id}/estimate">${formToken(req)}<div class="form-grid">${select('Tipo preventivo','estimate_type',[['initial','Preventivo iniziale'],['extra','Variazione / lavoro extra']],req.query.type==='extra'?'extra':'initial')}</div><div id="estimate-lines"><div class="estimate-line"><select name="line_kind"><option value="labor">Manodopera</option><option value="part">Ricambio</option><option value="service">Servizio</option></select><input name="line_description" placeholder="Descrizione operazione o ricambio" required><input name="line_quantity" type="number" step="0.01" min="0.01" value="1" required><input name="line_unit_price" type="number" step="0.01" min="0" value="${esc(s.hourly_rate)}" required><input name="line_vat_rate" type="number" step="0.01" min="0" value="22" required></div></div><button class="button" type="button" id="add-estimate-line">Aggiungi riga</button><div class="form-grid">${input('Valido fino al','valid_until','date')}${input('Note e condizioni','notes')}</div><button class="button primary">Salva bozza preventivo</button></form></section>`,req.session.user,'orders'));}catch(e){next(e);}});
app.post('/work-orders/:id/estimate',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const w=await c.query('SELECT id FROM work_orders WHERE id=$1 FOR UPDATE',[req.params.id]);if(!w.rowCount)throw new Error('Ordine di lavoro non trovato');const type=['initial','extra'].includes(req.body.estimate_type)?req.body.estimate_type:null;if(!type)throw new Error('Tipo preventivo non valido.');if(type==='extra'){const approved=await c.query(`SELECT 1 FROM estimates WHERE work_order_id=$1 AND status='approved' LIMIT 1`,[req.params.id]);if(!approved.rowCount)throw new Error('Prima della variazione deve esistere un preventivo iniziale approvato.');}const arr=v=>Array.isArray(v)?v:[v];const kinds=arr(req.body.line_kind),desc=arr(req.body.line_description),qty=arr(req.body.line_quantity),price=arr(req.body.line_unit_price),vat=arr(req.body.line_vat_rate);const lines=desc.map((d,i)=>({kind:kinds[i],description:String(d||'').trim(),quantity:Number(qty[i]),price:Number(price[i]),vat:Number(vat[i])})).filter(x=>x.description);if(!lines.length||lines.length>100)throw new Error('Inserisci da 1 a 100 righe valide.');for(const l of lines){if(!['labor','part','service'].includes(l.kind)||!Number.isFinite(l.quantity)||l.quantity<=0||l.quantity>100000||!Number.isFinite(l.price)||l.price<0||l.price>100000000||!Number.isFinite(l.vat)||l.vat<0||l.vat>100)throw new Error('Controlla tipo, quantità, prezzo e aliquota delle righe.');}const n=await c.query('SELECT coalesce(max(version),0)+1 AS version FROM estimates WHERE work_order_id=$1',[req.params.id]);const e=await c.query(`INSERT INTO estimates(work_order_id,version,estimate_type,status,valid_until,notes) VALUES($1,$2,$3,'draft',$4,$5) RETURNING id`,[req.params.id,n.rows[0].version,type,req.body.valid_until||null,String(req.body.notes||'').slice(0,5000)]);for(const l of lines)await c.query(`INSERT INTO estimate_lines(estimate_id,kind,description,quantity,unit_price,vat_rate) VALUES($1,$2,$3,$4,$5,$6)`,[e.rows[0].id,l.kind,l.description,l.quantity,l.price,l.vat]);await c.query('COMMIT');flash(req,type==='extra'?'Variazione preventivo salvata in bozza.':'Preventivo iniziale salvato in bozza.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/work-orders/${req.params.id}/estimate/new`);}finally{c.release();}});
app.get('/estimates/:id/documents/:docid',needAuth,async(req,res,next)=>{try{const d=await pool.query(`SELECT id,file_name,mime_type,file_data FROM documents WHERE id=$1 AND estimate_id=$2 AND document_type='estimate_pdf'`,[req.params.docid,req.params.id]);if(!d.rowCount)return res.sendStatus(404);res.type(d.rows[0].mime_type).set('Content-Disposition',`inline; filename="${d.rows[0].file_name.replace(/["\\\r\n]/g,'_')}"`).send(d.rows[0].file_data);}catch(e){next(e);}});
app.post('/estimates/:id/decision',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const status=req.body.decision==='approved'?'approved':req.body.decision==='rejected'?'rejected':null;if(!status)throw new Error('Decisione non valida');const e=await c.query(`UPDATE estimates SET status=$1 WHERE id=$2 AND status IN ('draft','sent') RETURNING work_order_id,version`,[status,req.params.id]);if(!e.rowCount)throw new Error('Preventivo non trovato o già deciso.');if(status==='approved')await c.query(`UPDATE work_orders SET status='scheduled',updated_at=now() WHERE id=$1`,[e.rows[0].work_order_id]);else await c.query(`UPDATE work_orders SET status='quote_pending',updated_at=now() WHERE id=$1`,[e.rows[0].work_order_id]);await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,$2,'estimate',$3,$4)`,[req.session.user.id,status,String(req.params.id),JSON.stringify({version:e.rows[0].version})]);await c.query('COMMIT');flash(req,status==='approved'?'Preventivo approvato.':'Preventivo rifiutato.');res.redirect(`/work-orders/${e.rows[0].work_order_id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect('/work-orders');}finally{c.release();}});
app.post('/estimates/:id/customer-link',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{try{const estimate=await pool.query(`SELECT e.id,e.work_order_id,e.status,e.valid_until,e.version FROM estimates e WHERE e.id=$1`,[req.params.id]);if(!estimate.rowCount||!['draft','sent'].includes(estimate.rows[0].status))throw new Error('Il preventivo non è più disponibile per l’invio.');const token=crypto.randomBytes(32).toString('base64url'),hash=crypto.createHash('sha256').update(token).digest('hex');const expiryDate=estimate.rows[0].valid_until?String(estimate.rows[0].valid_until).slice(0,10):null;const expires=expiryDate?new Date(parseRomeLocal(`${expiryDate}T23:59`)):new Date(Date.now()+7*86400000);await pool.query(`UPDATE estimates SET status='sent' WHERE id=$1 AND status IN ('draft','sent')`,[req.params.id]);await pool.query('INSERT INTO customer_action_tokens(token_hash,estimate_id,expires_at,created_by) VALUES($1,$2,$3,$4)',[hash,req.params.id,expires,req.session.user.id]);const url=`${req.protocol}://${req.get('host')}/customer/approve/${token}`;res.send(page('Link di approvazione cliente',`<section class="card"><h2>Link protetto pronto</h2><p>Scade il ${fmtDate(expires)} e può registrare una sola risposta. Copialo e invialo al cliente con il canale concordato.</p><label>Link cliente<input id="customer-approval-link" readonly value="${esc(url)}"></label><button type="button" class="button primary" data-copy="#customer-approval-link">Copia link</button> <a class="button" href="/estimates/${req.params.id}/pdf">Apri PDF preventivo</a><p><a href="/work-orders/${estimate.rows[0].work_order_id}">Torna all’ordine di lavoro</a></p></section>`,req.session.user,'orders'));}catch(e){flash(req,e.message);res.redirect('/work-orders');}});
app.get('/customer/portal/:token',async(req,res,next)=>{try{const hash=crypto.createHash('sha256').update(String(req.params.token||'')).digest('hex');const q=await pool.query(`SELECT c.id,c.name,t.expires_at FROM customer_portal_tokens t JOIN customers c ON c.id=t.customer_id WHERE t.token_hash=$1 AND t.revoked_at IS NULL AND t.expires_at>now()`,[hash]);if(!q.rowCount)return res.status(410).send(page('Link portale non valido','<section class="card"><h2>Link scaduto o non più disponibile</h2><p>Contatta l’officina per un nuovo accesso.</p></section>'));const c=q.rows[0],orders=await pool.query(`SELECT w.id,w.status,w.updated_at,v.plate,v.make,v.model FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id WHERE w.customer_id=$1 AND w.status<>'cancelled' ORDER BY w.updated_at DESC LIMIT 30`,[c.id]);const rows=orders.rows.map(o=>`<tr><td>${esc(o.plate)}</td><td>${esc(o.make)} ${esc(o.model)}</td><td>GO-${o.id}</td><td><span class="badge">${esc(statuses[o.status]||o.status)}</span></td><td>${fmtDate(o.updated_at)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun intervento registrato</td></tr>';res.send(page('Portale cliente',`<section class="card"><p class="eyebrow">GO · GESTIONE OFFICINA</p><h2>Benvenuto, ${esc(c.name)}</h2><p>Stato aggiornato degli interventi associati al tuo profilo. Per dettagli o documenti contatta direttamente l’officina.</p><div class="table-wrap"><table><thead><tr><th>Targa</th><th>Veicolo</th><th>Ordine</th><th>Stato</th><th>Aggiornato</th></tr></thead><tbody>${rows}</tbody></table></div><p class="muted">Questo collegamento è personale e scade il ${fmtDate(c.expires_at)}. La data di appuntamento non è una promessa di consegna.</p></section>`));}catch(e){next(e);}});
app.get('/customer/approve/:token',async(req,res,next)=>{try{const hash=crypto.createHash('sha256').update(String(req.params.token||'')).digest('hex');const q=await pool.query(`SELECT e.*,w.id AS order_id,c.name AS customer,v.plate,v.make,v.model FROM customer_action_tokens t JOIN estimates e ON e.id=t.estimate_id JOIN work_orders w ON w.id=e.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id WHERE t.token_hash=$1 AND t.used_at IS NULL AND t.expires_at>now() AND e.status IN ('draft','sent')`,[hash]);if(!q.rowCount)return res.status(410).send(page('Link non valido','<section class="card"><h2>Link scaduto o già utilizzato</h2><p>Contatta l’officina per ricevere un nuovo link.</p></section>'));const e=q.rows[0],lines=await pool.query('SELECT * FROM estimate_lines WHERE estimate_id=$1 ORDER BY id',[e.id]);const total=lines.rows.reduce((sum,l)=>sum+Number(l.quantity)*Number(l.unit_price)*(1+Number(l.vat_rate)/100),0);const rows=lines.rows.map(l=>`<tr><td>${esc(l.description)}</td><td>${Number(l.quantity)}</td><td>${money(l.unit_price)}</td><td>${l.vat_rate}%</td><td>${money(Number(l.quantity)*Number(l.unit_price)*(1+Number(l.vat_rate)/100))}</td></tr>`).join('');res.send(page('Esamina preventivo',`<section class="card"><span class="eyebrow">GO-${e.order_id} · VERSIONE ${e.version}</span><h2>${e.estimate_type==='extra'?'Variazione / lavoro extra':'Preventivo officina'}</h2><p>${esc(e.customer)} · ${esc(e.plate)} ${esc(e.make)} ${esc(e.model)}</p><p>Valido fino al ${fmtDate(e.valid_until)}. ${esc(e.notes)}</p><div class="table-wrap"><table><thead><tr><th>Descrizione</th><th>Q.tà</th><th>Prezzo</th><th>IVA</th><th>Totale</th></tr></thead><tbody>${rows}</tbody></table></div><h2>Totale: ${money(total)}</h2><form method="post" action="/customer/approve/${encodeURIComponent(req.params.token)}">${formToken(req)}${input('Nome della persona che risponde','responded_by','text','',true)}<p>La risposta verrà registrata per questa specifica versione del preventivo.</p><button class="button primary" name="decision" value="approved">Approvo il preventivo</button> <button class="button" name="decision" value="rejected">Rifiuto il preventivo</button></form></section>`));}catch(e){next(e);}});
app.post('/customer/approve/:token',async(req,res,next)=>{const c=await pool.connect();try{const decision=['approved','rejected'].includes(req.body.decision)?req.body.decision:null,respondedBy=String(req.body.responded_by||'').trim();if(!decision||!respondedBy)throw new Error('Indica il nome e una decisione valida.');const hash=crypto.createHash('sha256').update(String(req.params.token||'')).digest('hex');await c.query('BEGIN');const q=await c.query(`SELECT t.id AS token_id,e.id AS estimate_id,e.work_order_id,e.version FROM customer_action_tokens t JOIN estimates e ON e.id=t.estimate_id WHERE t.token_hash=$1 AND t.used_at IS NULL AND t.expires_at>now() AND e.status IN ('draft','sent') FOR UPDATE OF t,e`,[hash]);if(!q.rowCount)throw new Error('Il link è scaduto o è già stato utilizzato.');const e=q.rows[0];await c.query('UPDATE customer_action_tokens SET used_at=now() WHERE id=$1',[e.token_id]);await c.query('UPDATE estimates SET status=$1 WHERE id=$2',[decision,e.estimate_id]);await c.query('INSERT INTO estimate_customer_responses(estimate_id,decision,responded_by,estimate_version,evidence) VALUES($1,$2,$3,$4,$5)',[e.estimate_id,decision,respondedBy,e.version,JSON.stringify({method:'protected_single_use_link',user_agent:String(req.get('user-agent')||'').slice(0,300)})]);if(decision==='approved')await c.query(`UPDATE work_orders SET status='scheduled',updated_at=now() WHERE id=$1`,[e.work_order_id]);await c.query('INSERT INTO audit_log(action,entity_type,entity_id,details) VALUES($1,$2,$3,$4)',[`customer_${decision}`,'estimate',String(e.estimate_id),JSON.stringify({version:e.version,responded_by:respondedBy})]);await c.query('COMMIT');res.send(page('Risposta registrata',`<section class="card"><h2>${decision==='approved'?'Preventivo approvato':'Preventivo rifiutato'}</h2><p>La tua risposta è stata registrata per la versione ${e.version}. Puoi chiudere questa pagina.</p></section>`));}catch(e){await c.query('ROLLBACK');res.status(400).send(page('Risposta non registrata',`<section class="card"><h2>Non è stato possibile registrare la risposta</h2><p>${esc(e.message)}</p></section>`));}finally{c.release();}});
app.get('/estimates/:id/pdf',needAuth,async(req,res,next)=>{try{const e=await pool.query(`SELECT e.*,w.id AS order_id,c.name AS customer,v.plate,v.make,v.model,s.business_name,s.address,s.phone AS workshop_phone,s.email AS workshop_email,s.vat_number,s.logo_data FROM estimates e JOIN work_orders w ON w.id=e.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id CROSS JOIN workshop_settings s WHERE e.id=$1`,[req.params.id]);if(!e.rowCount)return res.sendStatus(404);const lines=await pool.query('SELECT * FROM estimate_lines WHERE estimate_id=$1 ORDER BY id',[req.params.id]);const d=e.rows[0];const pdf=new PDFDocument({size:'A4',margin:48});archivePdf(pdf,req,res,next,{documentType:'estimate_pdf',filename:`GO-Preventivo-${d.order_id}-v${d.version}.pdf`,workOrderId:d.order_id,estimateId:d.id});drawWorkshopLogo(pdf,d.logo_data);pdf.fillColor('#202a39').fontSize(20).font('Helvetica-Bold').text(d.business_name,205,48,{width:342});pdf.fontSize(9).font('Helvetica').fillColor('#667085').text([d.address,d.workshop_phone,d.workshop_email,d.vat_number?`P. IVA ${d.vat_number}`:''].filter(Boolean).join(' · '),205,74,{width:342});pdf.y=115;pdf.strokeColor('#ef6b22').lineWidth(2).moveTo(48,pdf.y).lineTo(547,pdf.y).stroke();pdf.moveDown().fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text(`PREVENTIVO GO-${d.order_id} · v${d.version}`);pdf.moveDown().fontSize(11).font('Helvetica').text(`Cliente: ${d.customer}`).text(`Veicolo: ${d.plate} · ${d.make} ${d.model}`).text(`Stato: ${d.status}`).text(`Validità: ${fmtDate(d.valid_until)}`);pdf.moveDown().font('Helvetica-Bold').text('Descrizione                         Q.tà       Prezzo       IVA        Totale');let net=0,tax=0;for(const l of lines.rows){const base=Number(l.quantity)*Number(l.unit_price);const iva=base*Number(l.vat_rate)/100;net+=base;tax+=iva;pdf.font('Helvetica').fontSize(10).text(`${l.description} · ${l.kind}       ${l.quantity}       ${money(l.unit_price)}       ${l.vat_rate}%       ${money(base+iva)}`);}pdf.moveDown().font('Helvetica-Bold').text(`Imponibile: ${money(net)}`).text(`IVA: ${money(tax)}`).text(`Totale preventivo: ${money(net+tax)}`);if(d.notes)pdf.moveDown().font('Helvetica').text(`Note: ${d.notes}`);pdf.moveDown(2).font('Helvetica').text('Approvazione cliente: __________________________     Data: ____ / ____ / ______');pdf.end();}catch(e){next(e);}});

app.get('/privacy-requests',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const [customers,requests]=await Promise.all([pool.query('SELECT id,name,email FROM customers ORDER BY name LIMIT 500'),pool.query(`SELECT p.*,c.name AS customer_name,u.name AS handler FROM privacy_requests p LEFT JOIN customers c ON c.id=p.customer_id LEFT JOIN users u ON u.id=p.handled_by ORDER BY p.received_at DESC LIMIT 300`)]);const customerOptions=[['','Non associato / contatto'],...customers.rows.map(c=>[c.id,`${c.name}${c.email?' · '+c.email:''}`])];const typeLabels={access:'Accesso',export:'Copia / esportazione',rectification:'Rettifica',deletion:'Cancellazione',restriction:'Limitazione',objection:'Opposizione',other:'Altro'};const rows=requests.rows.map(p=>`<tr><td>${fmtDate(p.received_at)}</td><td>${esc(p.customer_name||p.requester)}</td><td>${esc(typeLabels[p.request_type]||p.request_type)}</td><td>${esc(p.notes||'—')}</td><td>${esc(p.status)}</td><td>${p.status==='completed'||p.status==='rejected'?esc(p.handler||'—'):`<form class="inline-form" method="post" action="/privacy-requests/${p.id}/status">${formToken(req)}${select('Stato','status',[['in_review','In verifica'],['completed','Completata'],['rejected','Non accolta']],p.status)}<button class="button small">Aggiorna</button></form>`}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nessuna richiesta privacy registrata.</td></tr>';res.send(page('Richieste privacy',`${takeFlash(req)}<section class="card"><p class="muted">Registro operativo per richieste degli interessati. La verifica dell’identità, dei termini e delle eccezioni legali resta a carico dell’officina e dei suoi consulenti.</p><form method="post" action="/privacy-requests">${formToken(req)}<div class="form-grid">${select('Cliente','customer_id',customerOptions)}${select('Tipo richiesta','request_type',Object.entries(typeLabels))}${input('Data ricezione','received_at','date',new Date().toISOString().slice(0,10),true)}</div><label>Richiedente e dettagli<textarea name="notes" required></textarea></label><button class="button primary">Registra richiesta</button></form></section><section class="card"><h2>Registro richieste</h2><div class="table-wrap"><table><thead><tr><th>Ricevuta</th><th>Interessato</th><th>Tipo</th><th>Dettagli</th><th>Stato</th><th>Gestione</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'settings'));}catch(e){next(e);}});
app.post('/privacy-requests',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const type=String(req.body.request_type||''),requester=String(req.body.notes||'').trim(),valid=new Set(['access','export','rectification','deletion','restriction','objection','other']);if(!valid.has(type)||!requester)throw new Error('Inserisci tipo e dettagli della richiesta.');const date=/^\\d{4}-\\d{2}-\\d{2}$/.test(req.body.received_at||'')?req.body.received_at:new Date().toISOString().slice(0,10);const result=await pool.query(`INSERT INTO privacy_requests(customer_id,request_type,requester,notes,received_at,due_at) VALUES($1,$2,$3,$3,$4::date,($4::date+30)) RETURNING id`,[req.body.customer_id||null,type,requester.slice(0,4000),date]);await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'privacy_request_received','privacy_request',$2,$3)`,[req.session.user.id,String(result.rows[0].id),JSON.stringify({type,customer_id:req.body.customer_id||null})]);flash(req,'Richiesta registrata con scadenza indicativa a 30 giorni; verifica i termini applicabili.');res.redirect('/privacy-requests');}catch(e){flash(req,e.message);res.redirect('/privacy-requests');}});
app.post('/privacy-requests/:id/status',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{if(!['in_review','completed','rejected'].includes(req.body.status))throw new Error('Stato non valido.');const r=await pool.query(`UPDATE privacy_requests SET status=$1,handled_by=$2,completed_at=CASE WHEN $1 IN ('completed','rejected') THEN now() ELSE NULL END WHERE id=$3 RETURNING id`,[req.body.status,req.session.user.id,req.params.id]);if(!r.rowCount)throw new Error('Richiesta non trovata.');await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'privacy_request_status','privacy_request',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({status:req.body.status})]);flash(req,'Stato richiesta aggiornato.');res.redirect('/privacy-requests');}catch(e){flash(req,e.message);res.redirect('/privacy-requests');}});
app.get('/reports',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const from=/^\\d{4}-\\d{2}-\\d{2}$/.test(req.query.from||'')?req.query.from:new Date(Date.now()-30*86400000).toISOString().slice(0,10),to=/^\\d{4}-\\d{2}-\\d{2}$/.test(req.query.to||'')?req.query.to:new Date().toISOString().slice(0,10);const q=await pool.query(`WITH invoice_totals AS (SELECT i.id,i.issue_date,i.status,w.id AS order_id,c.name AS customer,v.plate,coalesce(sum(l.quantity*l.unit_price*(1+l.vat_rate/100)),0)::numeric AS total FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id LEFT JOIN invoice_lines l ON l.invoice_id=i.id WHERE i.issue_date BETWEEN $1::date AND $2::date GROUP BY i.id,w.id,c.name,v.plate),paid AS (SELECT invoice_id,sum(amount)::numeric AS amount FROM payments GROUP BY invoice_id) SELECT it.*,coalesce(p.amount,0)::numeric AS paid,it.total-coalesce(p.amount,0)::numeric AS due FROM invoice_totals it LEFT JOIN paid p ON p.invoice_id=it.id ORDER BY it.issue_date DESC,it.id DESC`,[from,to]);const totals=q.rows.reduce((a,r)=>({total:a.total+Number(r.total),paid:a.paid+Number(r.paid),due:a.due+Number(r.due)}),{total:0,paid:0,due:0});const rows=q.rows.map(r=>`<tr><td>${fmtDate(r.issue_date)}</td><td><a href="/invoices/${r.id}">${esc(r.order_id)}</a></td><td>${esc(r.customer)}</td><td>${esc(r.plate)}</td><td>${money(r.total)}</td><td>${money(r.paid)}</td><td>${money(r.due)}</td><td>${esc(r.status)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Nessun documento nell’intervallo</td></tr>';res.send(page('Report gestionali',`${takeFlash(req)}<section class="card"><p class="muted">Riepilogo documenti gestionali e pagamenti per data di emissione. Non è un report fiscale né include costi/margini non registrati.</p><form class="inline-form" method="get" action="/reports">${input('Dal','from','date',from,true)}${input('Al','to','date',to,true)}<button class="button primary">Applica filtri</button><a class="button" href="/reports.csv?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}">Esporta CSV</a></form><div class="stats"><article class="stat card"><span>Totale documenti</span><strong>${money(totals.total)}</strong></article><article class="stat card"><span>Incassato</span><strong>${money(totals.paid)}</strong></article><article class="stat card"><span>Residuo</span><strong>${money(totals.due)}</strong></article></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Ordine</th><th>Cliente</th><th>Targa</th><th>Totale</th><th>Pagato</th><th>Residuo</th><th>Stato</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'reports'));}catch(e){next(e);}});
app.get('/reports.csv',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const from=/^\\d{4}-\\d{2}-\\d{2}$/.test(req.query.from||'')?req.query.from:new Date(Date.now()-30*86400000).toISOString().slice(0,10),to=/^\\d{4}-\\d{2}-\\d{2}$/.test(req.query.to||'')?req.query.to:new Date().toISOString().slice(0,10);const q=await pool.query(`SELECT i.issue_date,i.invoice_number,c.name AS customer,v.plate,coalesce(sum(l.quantity*l.unit_price*(1+l.vat_rate/100)),0)::numeric AS total,coalesce((SELECT sum(p.amount) FROM payments p WHERE p.invoice_id=i.id),0)::numeric AS paid,i.status FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id LEFT JOIN invoice_lines l ON l.invoice_id=i.id WHERE i.issue_date BETWEEN $1::date AND $2::date GROUP BY i.id,c.name,v.plate ORDER BY i.issue_date,i.id`,[from,to]);const csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';res.type('text/csv; charset=utf-8').set('Content-Disposition','attachment; filename="go-report.csv"').send(['data;numero;cliente;targa;totale;incassato;residuo;stato',...q.rows.map(r=>[r.issue_date,r.invoice_number,r.customer,r.plate,money(r.total),money(r.paid),money(Number(r.total)-Number(r.paid)),r.status].map(csvCell).join(';'))].join('\\r\\n'));}catch(e){next(e);}});
app.get('/invoices',needAuth,allow('owner','admin','manager','accounting','accountant'),async(req,res,next)=>{try{const r=await pool.query(`SELECT i.*,c.name AS customer,v.plate,coalesce(sum(p.amount),0) AS paid FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id LEFT JOIN payments p ON p.invoice_id=i.id GROUP BY i.id,c.name,v.plate ORDER BY i.created_at DESC LIMIT 300`);const rows=await Promise.all(r.rows.map(async i=>{const total=await pool.query(`SELECT coalesce(sum(quantity*unit_price*(1+vat_rate/100)),0)::numeric AS amount FROM invoice_lines WHERE invoice_id=$1`,[i.id]);const due=Number(total.rows[0].amount);return `<tr><td><a href="/invoices/${i.id}">${esc(i.invoice_number)}</a></td><td>${esc(i.customer)}</td><td>${esc(i.plate)}</td><td>${fmtDate(i.issue_date)}</td><td>${money(due)}</td><td>${money(i.paid)}</td><td><span class="badge">${esc(i.status)}</span></td></tr>`;}));res.send(page('Fatture e pagamenti',`${takeFlash(req)}<section class="card"><p class="muted">Documenti gestionali e pagamenti registrati. L’emissione fiscale richiede l’integrazione con il sistema configurato dall’officina.</p><div class="table-wrap"><table><thead><tr><th>Numero</th><th>Cliente</th><th>Targa</th><th>Data</th><th>Totale</th><th>Pagato</th><th>Stato</th></tr></thead><tbody>${rows.join('')||'<tr><td colspan="7" class="empty">Nessun documento</td></tr>'}</tbody></table></div></section>`,req.session.user,'invoices'));}catch(e){next(e);}});
app.get('/invoices/:id',needAuth,allow('owner','admin','manager','accounting','accountant'),async(req,res,next)=>{try{const q=await pool.query(`SELECT i.*,c.name AS customer,v.plate,v.make,v.model,v.mileage AS vehicle_mileage FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id WHERE i.id=$1`,[req.params.id]);if(!q.rowCount)return res.sendStatus(404);const i=q.rows[0];const [lines,pays,total]=await Promise.all([pool.query('SELECT * FROM invoice_lines WHERE invoice_id=$1 ORDER BY id',[i.id]),pool.query('SELECT * FROM payments WHERE invoice_id=$1 ORDER BY paid_at',[i.id]),pool.query('SELECT coalesce(sum(quantity*unit_price*(1+vat_rate/100)),0)::numeric AS amount FROM invoice_lines WHERE invoice_id=$1',[i.id])]);const grand=Number(total.rows[0].amount),paid=pays.rows.reduce((n,p)=>n+Number(p.amount),0),due=Math.max(0,grand-paid);const lineRows=lines.rows.map(l=>`<tr><td>${esc(l.description)}</td><td>${Number(l.quantity)}</td><td>${money(l.unit_price)}</td><td>${l.vat_rate}%</td><td>${money(Number(l.quantity)*Number(l.unit_price)*(1+Number(l.vat_rate)/100))}</td></tr>`).join('');const payRows=pays.rows.map(p=>`<tr><td>${fmtDate(p.paid_at)}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td><td>${esc(p.reference)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun pagamento</td></tr>';const deliver=['owner','admin','manager','reception'].includes(req.session.user.role)&&i.status==='paid'?`<section class="card"><form method="post" action="/work-orders/${i.work_order_id}/deliver">${formToken(req)}<h2>Consegna veicolo</h2><div class="form-grid">${input('Consegnato a','received_by','text','',true)}${input('Km alla consegna','mileage_out','number',String(i.vehicle_mileage),true)}</div><label>Note consegna<textarea name="notes"></textarea></label><button class="button primary">Registra consegna</button><p class="muted">Verifica persona che ritira e chilometraggio prima di confermare.</p></form></section>`:'';const body=`${takeFlash(req)}<section class="card"><div class="section-heading"><div><span class="eyebrow">DOCUMENTO GESTIONALE · NON FISCALE</span><h2>${esc(i.invoice_number)}</h2><p class="muted">${esc(i.customer)} · ${esc(i.plate)} ${esc(i.make)} ${esc(i.model)}</p></div><a class="button" href="/invoices/${i.id}/pdf">PDF stampabile</a></div><div class="table-wrap"><table><thead><tr><th>Descrizione</th><th>Q.tà</th><th>Prezzo</th><th>IVA</th><th>Totale riga</th></tr></thead><tbody>${lineRows}</tbody></table></div><div class="totals"><strong>Totale: ${money(grand)}</strong><strong>Pagato: ${money(paid)}</strong><strong>Residuo: ${money(due)}</strong></div>${i.status==='draft'?`<form method="post" action="/invoices/${i.id}/issue">${formToken(req)}<button class="button primary">Conferma documento gestionale</button></form>`:''}</section><section class="card"><h2>Pagamenti</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Metodo</th><th>Importo</th><th>Riferimento</th></tr></thead><tbody>${payRows}</tbody></table></div>${due>0&&i.status!=='draft'&&i.status!=='void'?`<form class="inline-form" method="post" action="/invoices/${i.id}/payments">${formToken(req)}${input('Importo (€)','amount','number',due.toFixed(2),true)}${select('Metodo','method',[['cash','Contanti'],['card','Carta'],['bank_transfer','Bonifico'],['other','Altro']])}${input('Riferimento','reference')}<button class="button primary">Registra pagamento</button></form>`:''}</section>${deliver}`;res.send(page(`Documento ${i.invoice_number}`,body,req.session.user,'invoices'));}catch(e){next(e);}});
app.post('/work-orders/:id/invoice',needAuth,allow('owner','admin','accounting'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const w=await c.query(`SELECT w.id,w.status FROM work_orders w WHERE w.id=$1 FOR UPDATE`,[req.params.id]);if(!w.rowCount)throw new Error('Ordine non trovato.');if(w.rows[0].status!=='ready')throw new Error('Il documento può essere preparato dopo il superamento dei controlli e del test.');const approved=await c.query(`SELECT id FROM estimates WHERE work_order_id=$1 AND status='approved' ORDER BY version DESC LIMIT 1`,[req.params.id]);if(!approved.rowCount)throw new Error('Serve un preventivo approvato.');const existing=await c.query(`SELECT id FROM invoices WHERE work_order_id=$1 AND status<>'void'`,[req.params.id]);if(existing.rowCount)throw new Error('Esiste già un documento per questo ordine.');const number=`GO-${new Date().getFullYear()}-${String(req.params.id).padStart(6,'0')}`;const inv=await c.query(`INSERT INTO invoices(work_order_id,invoice_number,status,created_by) VALUES($1,$2,'draft',$3) RETURNING id`,[req.params.id,number,req.session.user.id]);await c.query(`INSERT INTO invoice_lines(invoice_id,kind,description,quantity,unit_price,vat_rate) SELECT $1,kind,description,quantity,unit_price,vat_rate FROM estimate_lines WHERE estimate_id=$2`,[inv.rows[0].id,approved.rows[0].id]);await c.query('COMMIT');res.redirect(`/invoices/${inv.rows[0].id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}finally{c.release();}});
app.post('/invoices/:id/issue',needAuth,allow('owner','admin','accounting'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const r=await c.query(`SELECT work_order_id,status FROM invoices WHERE id=$1 FOR UPDATE`,[req.params.id]);if(!r.rowCount||r.rows[0].status!=='draft')throw new Error('Documento non trovato o già confermato.');const amount=await c.query(`SELECT coalesce(sum(quantity*unit_price*(1+vat_rate/100)),0) AS amount FROM invoice_lines WHERE invoice_id=$1`,[req.params.id]);const order=await c.query(`UPDATE work_orders SET status='invoiced',updated_at=now() WHERE id=$1 AND status='ready' RETURNING id`,[r.rows[0].work_order_id]);if(!order.rowCount)throw new Error('L’ordine non risulta pronto per la fatturazione gestionale.');const status=Number(amount.rows[0].amount)<=0?'paid':'open';await c.query(`UPDATE invoices SET status=$1 WHERE id=$2`,[status,req.params.id]);await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'issue_invoice','invoice',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({status,total:Number(amount.rows[0].amount)})]);await c.query('COMMIT');flash(req,status==='paid'?'Documento gestionale a saldo zero confermato. Non è un’emissione fiscale.':'Documento gestionale confermato come aperto. Non è un’emissione fiscale.');res.redirect(`/invoices/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/invoices/${req.params.id}`);}finally{c.release();}});
app.post('/invoices/:id/payments',needAuth,allow('owner','admin','accounting'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const inv=await c.query('SELECT id FROM invoices WHERE id=$1 AND status IN (\'open\',\'partial\') FOR UPDATE',[req.params.id]);if(!inv.rowCount)throw new Error('Il documento non è aperto ai pagamenti.');const total=await c.query(`SELECT coalesce(sum(quantity*unit_price*(1+vat_rate/100)),0) AS amount FROM invoice_lines WHERE invoice_id=$1`,[req.params.id]);const paid=await c.query('SELECT coalesce(sum(amount),0) AS amount FROM payments WHERE invoice_id=$1',[req.params.id]);const amount=Number(req.body.amount),due=Number(total.rows[0].amount)-Number(paid.rows[0].amount);if(!Number.isFinite(amount)||amount<=0||amount>due+.005)throw new Error('Importo non valido o superiore al residuo.');if(!['cash','card','bank_transfer','other'].includes(req.body.method))throw new Error('Metodo di pagamento non valido.');await c.query('INSERT INTO payments(invoice_id,amount,method,reference,created_by) VALUES($1,$2,$3,$4,$5)',[req.params.id,amount,req.body.method,String(req.body.reference||'').slice(0,180),req.session.user.id]);const newPaid=Number(paid.rows[0].amount)+amount;await c.query('UPDATE invoices SET status=$1 WHERE id=$2',[newPaid+.005>=Number(total.rows[0].amount)?'paid':'partial',req.params.id]);await c.query('COMMIT');flash(req,'Pagamento registrato.');res.redirect(`/invoices/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/invoices/${req.params.id}`);}finally{c.release();}});
app.post('/work-orders/:id/deliver',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const w=await c.query('SELECT w.id,w.vehicle_id,w.status,v.mileage FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id WHERE w.id=$1 FOR UPDATE OF w,v',[req.params.id]);if(!w.rowCount)throw new Error('Ordine non trovato.');if(w.rows[0].status!=='invoiced')throw new Error('L’ordine deve superare i controlli ed essere documentato prima della consegna.');const unpaid=await c.query(`SELECT 1 FROM invoices i WHERE i.work_order_id=$1 AND i.status<>'paid' AND i.status<>'void' LIMIT 1`,[req.params.id]);if(unpaid.rowCount)throw new Error('Per registrare la consegna, salda prima il documento aperto.');const missing=await c.query(`SELECT 1 FROM invoices WHERE work_order_id=$1 AND status='paid'`,[req.params.id]);if(!missing.rowCount)throw new Error('Registra il documento e il pagamento prima della consegna.');const mileage=Number(req.body.mileage_out);const receiver=String(req.body.received_by||'').trim();if(!receiver||!Number.isInteger(mileage)||mileage<Number(w.rows[0].mileage))throw new Error('Inserisci chi ritira e un chilometraggio finale non inferiore a quello registrato.');await c.query(`INSERT INTO vehicle_deliveries(work_order_id,received_by,mileage_out,notes,user_id) VALUES($1,$2,$3,$4,$5)`,[req.params.id,receiver,mileage,String(req.body.notes||'').slice(0,2000),req.session.user.id]);await c.query(`UPDATE work_orders SET status='delivered',updated_at=now() WHERE id=$1`,[req.params.id]);await c.query(`UPDATE vehicles SET mileage=$1 WHERE id=$2`,[mileage,w.rows[0].vehicle_id]);await c.query('COMMIT');flash(req,'Consegna registrata.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/invoices`);}finally{c.release();}});
app.get('/invoices/:id/pdf',needAuth,allow('owner','admin','manager','accounting','accountant'),async(req,res,next)=>{try{const q=await pool.query(`SELECT i.*,w.id AS order_id,c.name AS customer,v.plate,v.make,v.model,s.business_name,s.address,s.phone,s.email,s.vat_number,s.logo_data FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id CROSS JOIN workshop_settings s WHERE i.id=$1`,[req.params.id]);if(!q.rowCount)return res.sendStatus(404);const d=q.rows[0],lines=await pool.query('SELECT * FROM invoice_lines WHERE invoice_id=$1 ORDER BY id',[d.id]);const pdf=new PDFDocument({size:'A4',margin:48});archivePdf(pdf,req,res,next,{documentType:'invoice_pdf',filename:`${d.invoice_number}.pdf`,workOrderId:d.order_id,invoiceId:d.id});drawWorkshopLogo(pdf,d.logo_data);pdf.fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text(d.business_name,205,48,{width:342});pdf.fillColor('#667085').fontSize(8).font('Helvetica').text([d.address,d.phone,d.email,d.vat_number?`P. IVA ${d.vat_number}`:''].filter(Boolean).join(' · '),205,74,{width:342});pdf.y=115;pdf.strokeColor('#ef6b22').lineWidth(2).moveTo(48,pdf.y).lineTo(547,pdf.y).stroke();pdf.moveDown().fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text('DOCUMENTO GESTIONALE · NON FISCALE');pdf.fontSize(12).font('Helvetica').text(`Numero: ${d.invoice_number}`).text(`Data: ${fmtDate(d.issue_date)}`).text(`Cliente: ${d.customer}`).text(`Veicolo: ${d.plate} · ${d.make} ${d.model}`).moveDown();let total=0;for(const l of lines.rows){const row=Number(l.quantity)*Number(l.unit_price)*(1+Number(l.vat_rate)/100);total+=row;pdf.fontSize(10).text(`${l.description} · ${l.quantity} × ${money(l.unit_price)} + IVA ${l.vat_rate}% = ${money(row)}`);}pdf.moveDown().font('Helvetica-Bold').fontSize(13).text(`Totale gestionale: ${money(total)}`);pdf.moveDown().fontSize(8).fillColor('#667085').text('Questo documento non è una fattura fiscale e non sostituisce il sistema di fatturazione elettronica configurato dall’officina.');pdf.end();}catch(e){next(e);}});
app.get('/invoices/:id/documents/:docid',needAuth,async(req,res,next)=>{try{const d=await pool.query('SELECT * FROM documents WHERE id=$1 AND invoice_id=$2',[req.params.docid,req.params.id]);if(!d.rowCount)return res.sendStatus(404);res.type(d.rows[0].mime_type).send(d.rows[0].file_data);}catch(e){next(e);}});

app.get('/inventory',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const r=await pool.query(`SELECT i.*,i.quantity-coalesce((SELECT sum(quantity) FROM inventory_reservations r WHERE r.item_id=i.id AND r.status='reserved'),0) AS available,coalesce((SELECT sum(quantity) FROM inventory_reservations r WHERE r.item_id=i.id AND r.status='reserved'),0) AS reserved FROM inventory_items i ORDER BY i.description LIMIT 500`);const rows=r.rows.map(i=>`<tr><td>${esc(i.sku)}</td><td><a href="/inventory/${i.id}">${esc(i.description)}</a></td><td>${esc(i.location)}</td><td>${Number(i.quantity).toLocaleString('it-IT')}</td><td>${Number(i.reserved).toLocaleString('it-IT')}</td><td>${Number(i.available).toLocaleString('it-IT')}</td><td>${Number(i.minimum_quantity).toLocaleString('it-IT')}</td><td>${money(i.unit_cost)}</td><td>${Number(i.available)<=Number(i.minimum_quantity)?'<span class="badge warning">Riordinare</span>':'<span class="badge good">Disponibile</span>'}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">Magazzino vuoto</td></tr>';res.send(page('Magazzino ricambi',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Giacenza fisica, riserve per commessa e quantità realmente disponibili.</p><div class="actions"><a class="button" href="/suppliers">Fornitori</a><a class="button" href="/purchases">Ordini fornitore</a><a class="button primary" href="/inventory/new">Nuovo articolo</a></div></div><div class="table-wrap"><table><thead><tr><th>Codice</th><th>Articolo</th><th>Ubicazione</th><th>Giacenza</th><th>Riservato</th><th>Disponibile</th><th>Minimo</th><th>Costo</th><th>Stato</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'inventory'));}catch(e){next(e);}});
app.get('/inventory/new',needAuth,allow('owner','admin','manager','warehouse'),(_req,res)=>res.send(page('Nuovo articolo',`<section class="card"><form method="post" action="/inventory">${formToken(_req)}<div class="form-grid">${input('Codice articolo','sku')}${input('Descrizione','description','text','',true)}${input('Ubicazione','location')}${input('Fornitore','supplier')}${input('Costo unitario','unit_cost','number','0')}${input('Prezzo unitario','unit_price','number','0')}${input('Giacenza iniziale','quantity','number','0')}${input('Scorta minima','minimum_quantity','number','0')}</div><button class="button primary">Crea articolo</button></form></section>`,_req.session.user,'inventory')));
app.post('/inventory',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const vals=[req.body.sku||'',req.body.description,req.body.location||'',req.body.supplier||'',req.body.unit_cost||0,req.body.unit_price||0,req.body.quantity||0,req.body.minimum_quantity||0];const r=await c.query(`INSERT INTO inventory_items(sku,description,location,supplier,unit_cost,unit_price,quantity,minimum_quantity) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id,quantity`,vals);if(Number(r.rows[0].quantity)!==0)await c.query(`INSERT INTO stock_movements(item_id,movement_type,quantity,reason,user_id) VALUES($1,'initial_load',$2,'Giacenza iniziale',$3)`,[r.rows[0].id,r.rows[0].quantity,req.session.user.id]);await c.query('COMMIT');flash(req,'Articolo creato.');res.redirect('/inventory');}catch(e){await c.query('ROLLBACK');next(e);}finally{c.release();}});
app.post('/inventory/:id/movement',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query('SELECT id,quantity FROM inventory_items WHERE id=$1 FOR UPDATE',[req.params.id]);if(!q.rowCount)throw new Error('Articolo non trovato.');const i=q.rows[0],type=String(req.body.movement_type||''),value=Number(req.body.quantity),reason=String(req.body.reason||'').trim();if(!['inventory_count','stock_correction','supplier_return','warranty_defective','customer_return'].includes(type)||!Number.isFinite(value)||!reason)throw new Error('Completa tipo, quantità e motivo del movimento.');let delta=value;if(type==='inventory_count'){if(value<0)throw new Error('La quantità contata non può essere negativa.');delta=value-Number(i.quantity);}else if(type==='supplier_return'||type==='warranty_defective'){if(value<=0)throw new Error('La quantità resa deve essere maggiore di zero.');delta=-value;}else if(type==='customer_return'&&value<=0)throw new Error('La quantità resa deve essere maggiore di zero.');const reserved=await c.query(`SELECT coalesce(sum(quantity),0) AS qty FROM inventory_reservations WHERE item_id=$1 AND status='reserved'`,[i.id]);if(Number(i.quantity)+delta<Number(reserved.rows[0].qty))throw new Error('Il movimento lascerebbe meno scorta di quella già riservata.');await c.query('UPDATE inventory_items SET quantity=quantity+$1 WHERE id=$2',[delta,i.id]);await c.query(`INSERT INTO stock_movements(item_id,movement_type,quantity,reason,user_id) VALUES($1,$2,$3,$4,$5)`,[i.id,type,delta,reason.slice(0,500),req.session.user.id]);await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'stock_movement','inventory_item',$2,$3)`,[req.session.user.id,String(i.id),JSON.stringify({type,quantity:delta,reason})]);await c.query('COMMIT');flash(req,'Movimento registrato e giacenza aggiornata.');res.redirect(`/inventory/${i.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/inventory/${req.params.id}`);}finally{c.release();}});
app.get('/inventory/:id',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const item=await pool.query(`SELECT i.*,i.quantity-coalesce((SELECT sum(quantity) FROM inventory_reservations r WHERE r.item_id=i.id AND r.status='reserved'),0) AS available FROM inventory_items i WHERE i.id=$1`,[req.params.id]);if(!item.rowCount)return res.sendStatus(404);const i=item.rows[0];const [orders,reservations,movements]=await Promise.all([pool.query(`SELECT id FROM work_orders WHERE status NOT IN ('closed','cancelled') ORDER BY id DESC LIMIT 100`),pool.query(`SELECT r.*,w.id AS order_id,v.plate,c.name AS customer FROM inventory_reservations r JOIN work_orders w ON w.id=r.work_order_id JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id WHERE r.item_id=$1 ORDER BY r.created_at DESC LIMIT 100`,[i.id]),pool.query(`SELECT m.*,u.name FROM stock_movements m LEFT JOIN users u ON u.id=m.user_id WHERE m.item_id=$1 ORDER BY m.created_at DESC LIMIT 100`,[i.id])]);const orderOpts=orders.rows.map(o=>[o.id,`GO-${o.id}`]);const resRows=reservations.rows.map(r=>`<tr><td><a href="/work-orders/${r.order_id}">GO-${r.order_id} · ${esc(r.plate)}</a></td><td>${Number(r.quantity)}</td><td>${esc(r.status)}</td><td>${fmtDate(r.created_at)}</td><td>${r.status==='reserved'?`<form class="inline-form" method="post" action="/inventory/reservations/${r.id}/consume">${formToken(req)}<button class="button small primary">Scarica usato</button></form><form method="post" action="/inventory/reservations/${r.id}/release">${formToken(req)}<button class="button small">Annulla riserva</button></form>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessuna riserva per questo ricambio</td></tr>';const moveRows=movements.rows.map(m=>`<tr><td>${fmtDate(m.created_at)}</td><td>${esc(m.movement_type)}</td><td>${Number(m.quantity).toLocaleString('it-IT')}</td><td>${esc(m.reason)}</td><td>${esc(m.name||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun movimento</td></tr>';res.send(page(i.description,`${takeFlash(req)}<section class="card"><div class="detail-grid"><div><span class="muted">Codice</span><strong>${esc(i.sku||'—')}</strong></div><div><span class="muted">Giacenza fisica</span><strong>${Number(i.quantity)}</strong></div><div><span class="muted">Disponibile</span><strong>${Number(i.available)}</strong></div><div><span class="muted">Ubicazione</span><strong>${esc(i.location||'—')}</strong></div></div><form class="inline-form" method="post" action="/inventory/${i.id}/reservations">${formToken(req)}${select('Ordine di lavoro','work_order_id',orderOpts)}${input('Quantità da riservare','quantity','number','1',true)}<button class="button primary">Riserva ricambio</button></form></section><section class="card"><h2>Riserve per ordine</h2><div class="table-wrap"><table><thead><tr><th>Ordine</th><th>Quantità</th><th>Stato</th><th>Data</th><th>Azione</th></tr></thead><tbody>${resRows}</tbody></table></div></section><section class="card"><h2>Registra movimento, reso o inventario</h2><p class="muted">Le rettifiche sono tracciate. Un calo non può rendere negativa la quantità disponibile per gli ordini già riservati.</p><form class="form-grid" method="post" action="/inventory/${i.id}/movement">${formToken(req)}${select('Operazione','movement_type',[['inventory_count','Conteggio inventario'],['stock_correction','Rettifica positiva / negativa'],['supplier_return','Reso al fornitore'],['warranty_defective','Reso per difetto / garanzia'],['customer_return','Reso cliente']])}${input('Quantità (inventario: quantità contata; rettifica: variazione con segno)','quantity','number','0',true)}${input('Motivo e riferimento','reason','text','',true)}<button class="button primary">Registra movimento</button></form></section><section class="card"><h2>Movimenti di magazzino</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Tipo</th><th>Quantità (+ carico, − scarico)</th><th>Motivo</th><th>Utente</th></tr></thead><tbody>${moveRows}</tbody></table></div></section>`,req.session.user,'inventory'));}catch(e){next(e);}});
app.post('/inventory/:id/reservations',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const item=await c.query('SELECT id,quantity FROM inventory_items WHERE id=$1 FOR UPDATE',[req.params.id]);if(!item.rowCount)throw new Error('Ricambio non trovato.');const qty=Number(req.body.quantity);if(!Number.isFinite(qty)||qty<=0)throw new Error('La quantità deve essere maggiore di zero.');const order=await c.query(`SELECT id FROM work_orders WHERE id=$1 AND status NOT IN ('closed','cancelled')`,[req.body.work_order_id]);if(!order.rowCount)throw new Error('Ordine di lavoro non valido o chiuso.');const reserved=await c.query(`SELECT coalesce(sum(quantity),0) AS quantity FROM inventory_reservations WHERE item_id=$1 AND status='reserved'`,[req.params.id]);if(qty>Number(item.rows[0].quantity)-Number(reserved.rows[0].quantity))throw new Error('La quantità supera la disponibilità non riservata.');const r=await c.query(`INSERT INTO inventory_reservations(item_id,work_order_id,quantity,reserved_by) VALUES($1,$2,$3,$4) RETURNING id`,[req.params.id,req.body.work_order_id,qty,req.session.user.id]);await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'reserve','inventory_item',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({reservation_id:r.rows[0].id,work_order_id:req.body.work_order_id,quantity:qty})]);await c.query('COMMIT');flash(req,'Ricambio riservato all’ordine.');res.redirect(`/inventory/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/inventory/${req.params.id}`);}finally{c.release();}});
app.post('/inventory/reservations/:id/consume',needAuth,allow('owner','admin','manager','warehouse','mechanic'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query(`SELECT r.*,i.description,i.quantity AS stock FROM inventory_reservations r JOIN inventory_items i ON i.id=r.item_id WHERE r.id=$1 FOR UPDATE OF r,i`,[req.params.id]);if(!q.rowCount)throw new Error('Riserva non trovata.');const r=q.rows[0];if(r.status!=='reserved')throw new Error('La riserva non è più attiva.');if(Number(r.stock)<Number(r.quantity))throw new Error('Giacenza insufficiente: controlla i movimenti.');await c.query(`UPDATE inventory_items SET quantity=quantity-$1 WHERE id=$2`,[r.quantity,r.item_id]);await c.query(`UPDATE inventory_reservations SET status='consumed',updated_at=now() WHERE id=$1`,[r.id]);await c.query(`INSERT INTO stock_movements(item_id,work_order_id,movement_type,quantity,reason,user_id) VALUES($1,$2,'work_order_use',$3,$4,$5)`,[r.item_id,r.work_order_id,-Number(r.quantity),`Ricambio usato in GO-${r.work_order_id}`,req.session.user.id]);await c.query('COMMIT');flash(req,'Ricambio scaricato dalla giacenza e collegato all’ordine.');res.redirect(`/inventory/${r.item_id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect('/inventory');}finally{c.release();}});
app.post('/inventory/reservations/:id/release',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const r=await pool.query(`UPDATE inventory_reservations SET status='released',updated_at=now() WHERE id=$1 AND status='reserved' RETURNING item_id`,[req.params.id]);if(!r.rowCount)throw new Error('Riserva non attiva o già chiusa.');await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,'release_reservation','inventory_item',$2)`,[req.session.user.id,String(r.rows[0].item_id)]);flash(req,'Riserva annullata; la quantità è nuovamente disponibile.');res.redirect(`/inventory/${r.rows[0].item_id}`);}catch(e){flash(req,e.message);res.redirect('/inventory');}});

app.get('/suppliers',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const r=await pool.query('SELECT * FROM suppliers ORDER BY name');const rows=r.rows.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.vat_number||'—')}</td><td>${esc(s.phone||'—')}</td><td>${esc(s.email||'—')}</td><td>${s.active?'Attivo':'Archiviato'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun fornitore registrato</td></tr>';res.send(page('Fornitori',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Anagrafica fornitori per ricambi e ordini di acquisto.</p><a class="button primary" href="/suppliers/new">Nuovo fornitore</a></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Partita IVA</th><th>Telefono</th><th>Email</th><th>Stato</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'inventory'));}catch(e){next(e);}});
